
import { loggingService } from '../utils/loggingService';
import { generateRequestId, notifyDevToolsStart, notifyDevToolsEnd } from './common';
import { RuleModificationStrategy } from './RuleModificationStrategies';
import * as DebugInterceptor from './DebugInterceptor';
import * as RequestEditor from './RequestEditor';
import { captureResponseBodyForDebugger } from './responseCapture';
import * as GlobalDelay from './GlobalDelay';

const originalFetch = window.fetch;

/**
 * Strategy to monkey-patch window.fetch.
 * Intercepts requests to apply delay/mock rules or log to DevTools.
 */
export class FetchMonkeyPatchingStrategy {
  /**
   * @param {object} context - Shared context containing strategies and state.
   * @property {RuleStrategy} context.ruleStrategy
   * @property {ApiStrategy} context.apiStrategy
   * @property {function} context.isReady - Returns true if config is loaded.
   * @property {function} context.isEnabled - Returns true if interception is enabled.
   * @property {function} context.queueRequest - queues a callback to be executed later.
   */
  constructor(context) {
    this.context = context;
    this.active = false;
  }

  enable() {
    if (this.active) return;
    this.active = true;
    const self = this;

    window.fetch = async function (input, init = {}) {
      let logged = false;
      // Bypass if globally disabled, but we must use originalFetch.
      if (!self.context.isEnabled()) {
        return originalFetch.apply(this, arguments);
      }

      // Normalize URL
      let url = input;
      if (input instanceof Request) {
        url = input.url;
      }
      let fullUrl;
      try {
        const base = (window.location && window.location.origin && window.location.origin !== 'null')
          ? window.location.origin
          : 'http://localhost';
        fullUrl = new URL(url, base).href;
      } catch (e) {
        loggingService.error(`[mockforme] Failed to construct URL for Fetch: ${url}`, e);
        return originalFetch.apply(this, arguments);
      }
      const method = (init.method || (input instanceof Request ? input.method : 'GET')).toUpperCase();

      // Check if ready
      if (!self.context.isReady()) {
        loggingService.info(`[mockforme] Fetch queued (not ready) for ${fullUrl}`);
        return new Promise((resolve, reject) => {
          self.context.queueRequest(() => {
            // When executing from queue, call window.fetch again (which will hit this proxy again but ready will be true)
            window.fetch(input, init).then(resolve).catch(reject);
          });
        });
      }

      // Check if this is a redirected request we should skip rules for
      let skipRules = false;
      let inheritedMocked = !!init._mfm_is_mocked;
      if (init._mfm_skip_rules) {
        loggingService.info(`[mockforme] Skipping rules for redirected Fetch: ${fullUrl}`);
        skipRules = true;
        // Clean up the flag from init so it doesn't leak to the network
        delete init._mfm_skip_rules;
        delete init._mfm_is_mocked;
      }

      const requestId = generateRequestId();

      // --> Extract Request Data for Matching & Logging
      let reqHeaders = {};
      const h = new Headers(init.headers || {});
      if (input instanceof Request) {
        // Headers from Request object
        new Headers(input.headers).forEach((v, k) => {
          if (!h.has(k)) h.set(k, v);
        });
      }
      h.forEach((v, k) => reqHeaders[k] = v);

      let bodyToMatch = init.body;
      if (!bodyToMatch && (input instanceof Request)) {
        try {
          // Clone to avoid consuming the original request body
          bodyToMatch = await input.clone().text();
        } catch (e) { }
      }

      // Check Rules
      let ruleMatch = skipRules ? null : self.context.ruleStrategy.match(fullUrl, method, reqHeaders, bodyToMatch);

      // --> Apply Request Modifications
      if (ruleMatch && ruleMatch.modificationActions) {
        // 1. Query Params
        if (ruleMatch.modificationActions.modifyQueryParams?.enabled) {
          const newUrl = RuleModificationStrategy.modifyQueryParams(fullUrl, ruleMatch.modificationActions.modifyQueryParams);
          if (newUrl !== fullUrl) {
            fullUrl = newUrl;
            if (typeof input === 'string') input = fullUrl;
            else if (input instanceof Request) input = new Request(fullUrl, input);
            loggingService.info(`[mockforme] Modified Fetch URL: ${fullUrl}`);
          }
        }

        // 2. Request Headers
        if (ruleMatch.modificationActions.modifyRequestHeaders?.enabled) {
          const modifiedHeaders = RuleModificationStrategy.modifyRequestHeaders(reqHeaders, ruleMatch.modificationActions.modifyRequestHeaders);
          init.headers = modifiedHeaders;
          // Update reqHeaders for logging the FINAL sent headers
          reqHeaders = { ...modifiedHeaders };
        }

        // 3. Request Body
        if (ruleMatch.modificationActions.modifyRequestBody?.enabled) {
          const modifiedBody = RuleModificationStrategy.modifyRequestBody(bodyToMatch, ruleMatch.modificationActions.modifyRequestBody);
          if (modifiedBody !== bodyToMatch) {
            init.body = modifiedBody;
            // Update for logging
            bodyToMatch = modifiedBody;
          }
        }
      }

      // Notify Start
      let mapping = null;
      if (!ruleMatch) {
        mapping = self.context.apiStrategy.match(fullUrl, method);
      }
      const isMocked = inheritedMocked || !!mapping || !!ruleMatch;

      // Adapt ruleMatch for logging if present
      const ruleLogInfo = ruleMatch ? {
        type: ruleMatch.type,
        value: ruleMatch.config?.value ?? ruleMatch.config?.delay,
        redirectUrl: ruleMatch.config?.redirectUrl ?? ruleMatch.config?.url
      } : null;

      const startTime = notifyDevToolsStart(requestId, fullUrl, method, bodyToMatch, reqHeaders, ruleLogInfo, isMocked);

      // Apply Mocking (Rewriting URL)
      if (mapping) {
        loggingService.info(`[mockforme] Rewriting Fetch URL: ${fullUrl}`);

        const mockUrl = self.context.apiStrategy.getMockUrl(fullUrl);

        if (input instanceof Request) {
          input = new Request(mockUrl, input);
        } else {
          input = mockUrl;
        }

        // Add Headers
        if (!init.headers) init.headers = {};
        // Helper to add header safely
        const addHeader = (key, val) => {
          if (init.headers instanceof Headers) init.headers.set(key, val);
          else if (Array.isArray(init.headers)) init.headers.push([key, val]);
          else init.headers[key] = val;
        };

        if (self.context.apiStrategy.token) addHeader('mockforme', self.context.apiStrategy.token);
        if (mapping._ack) addHeader('x-mockforme-id', mapping._ack);
        // Flow-scoped mocks identify the target ApiResponse via `_ri_`
        // instead of `_ack` (they don't have a server-side cache key).
        // User mappings don't carry `_ri_`, so adding it conditionally
        // is a no-op for the existing path.
        if (mapping._ri_) addHeader('_ri_', mapping._ri_);
      } else {
        if (ruleMatch) loggingService.info(`[mockforme] Rule matched for ${fullUrl}, skipping mapping.`);
      }

      // Apply Rule Actions (Delay/Timeout/Redirect)
      if (ruleMatch && ruleMatch.strategy) {
        try {
          const result = await ruleMatch.strategy.execute(ruleMatch.config, { url: fullUrl, method });

          // Handle Redirect
          if (result && result.redirectUrl) {
            // Notify Redirect
            if (startTime) {
              notifyDevToolsEnd(
                requestId, "Redirecting", 302, { 'Location': result.redirectUrl }, startTime,
                { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
                ruleLogInfo, isMocked
              );
              logged = true;
            }
            loggingService.info(`[mockforme] Redirecting Fetch to ${result.redirectUrl}`);

            // Create new Request for redirection
            let redirectInput;
            if (input instanceof Request) {
              // Clone original request with new URL
              redirectInput = new Request(result.redirectUrl, input);
            } else {
              // Original was URL string, verify if we need to merge init
              redirectInput = new Request(result.redirectUrl, init);
            }

            // We should pass 'init' again if it contains overrides not in 'input'?
            // 'new Request(url, init)' merges them.
            // If 'input' was Request, 'new Request(newUrl, input)' copies input properties. 
            // But 'init' args (second arg to fetch) override 'input' props.
            // We should ideally call window.fetch(redirectInput, init) if init has relevant stuff?
            // Or just window.fetch(redirectInput).
            // If we use 'redirectInput = new Request(result.redirectUrl, input)', we baked 'input' into it.
            // What about 'init'? 
            // If we do 'window.fetch(redirectInput, init)', init overrides are applied *again'. This is correct.

            // Flag the next fetch call to skip rules to avoid loops and inherit mocked status
            const nextInit = { ...init, _mfm_skip_rules: true, _mfm_is_mocked: isMocked };
            return window.fetch(redirectInput, nextInit);
          }

        } catch (e) {
          // Handle Timeout or other errors
          if (e.isMockTimeout || e.message === "Network request failed (simulated timeout)") {
            if (startTime && !logged) {
              notifyDevToolsEnd(
                requestId, "Timeout", 0, {}, startTime,
                { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
                ruleLogInfo, isMocked,
                { name: "AbortError", message: "Timeout" }
              );
              logged = true;
            }
          }
          throw e;
        }
      }

      // ─── Outgoing-Request Editor ────────────────────────────────────
      // If the user opted this (method, url) into the request editor,
      // pause BEFORE the network call so they can edit headers / query
      // params / body. Same priority guard as the debugger: skip when
      // the request is owned by the mock/rule pipeline.
      const editRule = (!isMocked) ? RequestEditor.match(method, fullUrl) : null;
      if (editRule) {
        const queryParams = {};
        try {
          const u = new URL(fullUrl);
          u.searchParams.forEach((v, k) => { queryParams[k] = v; });
        } catch { /* ignore */ }

        const editResolution = await RequestEditor.intercept({
          requestId,
          ruleId: editRule.id,
          request: { method, url: fullUrl, headers: reqHeaders, body: bodyToMatch },
          queryParams,
        });

        if (editResolution.cancel) {
          if (startTime && !logged) {
            notifyDevToolsEnd(
              requestId, 'Cancelled (Editor)', 0, {}, startTime,
              { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
              ruleMatch, isMocked,
              { name: 'AbortError', message: 'Cancelled by MockForMe request editor' },
            );
            logged = true;
          }
          const err = new TypeError('Request cancelled by MockForMe request editor');
          err.isMockTimeout = true;
          throw err;
        }

        // Rebuild the URL with the user's query params (stripping any existing).
        try {
          const newUrl = new URL(fullUrl);
          [...newUrl.searchParams.keys()].forEach((k) => newUrl.searchParams.delete(k));
          Object.entries(editResolution.queryParams || {}).forEach(([k, v]) => {
            newUrl.searchParams.set(k, String(v ?? ''));
          });
          fullUrl = newUrl.href;
        } catch { /* leave fullUrl as-is on parse failure */ }

        // Apply the edited headers + body to init / input. We always reset
        // input to the URL string here so init.headers/body are authoritative.
        const editedHeaders = editResolution.headers || {};
        const editedBody = editResolution.body == null ? undefined : editResolution.body;
        const upper = method.toUpperCase();
        const allowsBody = upper !== 'GET' && upper !== 'HEAD';
        init = {
          ...init,
          method,
          headers: editedHeaders,
          body: allowsBody ? editedBody : undefined,
        };
        input = fullUrl;

        // Update the local view used by downstream logging.
        reqHeaders = { ...editedHeaders };
        bodyToMatch = allowsBody ? editedBody : undefined;
      }
      // ─── End Outgoing-Request Editor ────────────────────────────────

      // ─── Global Others-tab Delay ────────────────────────────────────
      // Apply only on the non-mocked / non-rule path. Settings sheet
      // controls the value (in seconds). 0 = off.
      if (!isMocked) {
        const delayValue = GlobalDelay.delayMs();
        if (delayValue > 0) {
          await new Promise((r) => setTimeout(r, delayValue));
        }
      }
      // ─── End Global Others-tab Delay ────────────────────────────────

      // Execute Original Fetch
      try {
        const response = await originalFetch(input, init);

        const resHeaders = {};
        response.headers.forEach((v, k) => resHeaders[k] = v);

        // ─── Live Debugger ──────────────────────────────────────────────
        // Only attach the debugger to true "Others" requests. Mocked or
        // rule-matched requests are owned by the mock/rule pipeline; the
        // debugger must not interfere with them — even if the user
        // previously marked this URL for debug from the Others tab.
        const debugRule = (!isMocked)
          ? DebugInterceptor.match(method, fullUrl)
          : null;
        if (debugRule) {
          const originalBodyText = await captureResponseBodyForDebugger(response, requestId);

          const resolution = await DebugInterceptor.intercept({
            requestId,
            ruleId: debugRule.id,
            request: { method, url: fullUrl, headers: reqHeaders, body: bodyToMatch },
            response: { statusCode: response.status, headers: resHeaders, body: originalBodyText },
          });

          if (resolution.simulateTimeout) {
            if (startTime && !logged) {
              notifyDevToolsEnd(
                requestId, 'Timeout (Debugger)', 0, {}, startTime,
                { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
                ruleMatch, isMocked,
                { name: 'AbortError', message: 'Timeout simulated by MockForMe debugger' },
              );
              logged = true;
            }
            const err = new TypeError('Network request failed (simulated by MockForMe debugger)');
            err.isMockTimeout = true;
            throw err;
          }

          if (resolution.delayMs > 0) {
            await new Promise((r) => setTimeout(r, resolution.delayMs));
          }

          const finalStatus = Number(resolution.statusCode) || response.status;
          const finalHeaders = resolution.headers && typeof resolution.headers === 'object'
            ? resolution.headers
            : resHeaders;
          const bodyForResponse = typeof resolution.body === 'string'
            ? resolution.body
            : (resolution.body == null ? '' : JSON.stringify(resolution.body));

          // Reflect the user-modified response in the Others tab too.
          if (startTime && !logged) {
            notifyDevToolsEnd(
              requestId, bodyForResponse, finalStatus, finalHeaders, startTime,
              { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
              ruleMatch, isMocked,
            );
            logged = true;
          }

          return new Response(bodyForResponse, {
            status: finalStatus,
            statusText: response.statusText,
            headers: new Headers(finalHeaders),
          });
        }
        // ─── End Live Debugger ──────────────────────────────────────────

        // Treat everything as a potential stream if there's a ReadableStream body.
        // This avoids missing long-polling/streaming requests that don't have standard headers.
        if (response.body && typeof response.body.tee === 'function') {
          try {
            const [s1, s2] = response.body.tee();
            const reader = s2.getReader();
            let captured = "";
            let chunks = 0;
            const decoder = new TextDecoder();

            // Notify start of response immediately to clear "Loading" state
            if (startTime && !logged) {
              notifyDevToolsEnd(
                requestId, "[Loading Response...]", response.status, resHeaders, startTime,
                { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
                ruleMatch, isMocked
              );
            }

            (async () => {
              try {
                while (true) {
                  const { done, value } = await reader.read();
                  if (done) break;

                  chunks++;
                  try {
                    captured += decoder.decode(value, { stream: true });
                  } catch (e) {
                    captured += "[Binary Data]";
                  }

                  // Update DevTools periodically: first few chunks, then every 10th
                  if (chunks <= 10 || chunks % 10 === 0) {
                    notifyDevToolsEnd(
                      requestId, captured + (done ? "" : "\n... [Streaming Active]"), response.status, resHeaders, startTime,
                      { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
                      ruleMatch, isMocked
                    );
                  }

                  // Cap it to avoid memory issues for infinite streams (e.g. 1MB or 500 chunks)
                  if (captured.length > 1024 * 1024 || chunks > 500) {
                    captured += "\n\n[Response truncated by MockForMe for performance]";
                    break;
                  }
                }

                // Final update when done
                notifyDevToolsEnd(
                  requestId, captured, response.status, resHeaders, startTime,
                  { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
                  ruleMatch, isMocked
                );

                reader.releaseLock();
              } catch (e) {
                loggingService.warn("[mockforme] Stream read error:", e);
              } finally {
                logged = true; // Mark as final logged
              }
            })();

            // Return the first teed stream to the application
            const proxyResponse = new Response(s1, {
              status: response.status,
              statusText: response.statusText,
              headers: response.headers
            });

            // Proxy metadata properties
            Object.defineProperty(proxyResponse, 'url', { value: response.url });
            Object.defineProperty(proxyResponse, 'redirected', { value: response.redirected });
            Object.defineProperty(proxyResponse, 'type', { value: response.type });

            return proxyResponse;
          } catch (e) {
            loggingService.error("[mockforme] Failed to tee response body:", e);
          }
        }

        // Fallback for responses without bodies or where teeing failed
        if (startTime && !logged) {
          const cloneForText = response.clone();
          cloneForText.text().then(text => {
            if (!logged) {
              notifyDevToolsEnd(
                requestId, text, response.status, resHeaders, startTime,
                { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
                ruleMatch, isMocked
              );
              logged = true;
            }
          }).catch(() => {
            notifyDevToolsEnd(
              requestId, "[No Body]", response.status, resHeaders, startTime,
              { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
              ruleMatch, isMocked
            );
            logged = true;
          });
        }


        // Check for Response Header Modifications
        if (ruleMatch && ruleMatch.modificationActions?.modifyResponseHeaders?.enabled) {
          const modifiedHeaders = RuleModificationStrategy.modifyResponseHeaders(resHeaders, ruleMatch.modificationActions.modifyResponseHeaders);

          return new Response(response.body, {
            status: response.status,
            statusText: response.statusText,
            headers: modifiedHeaders
          });
        }

        return response;
      } catch (e) {
        if (startTime && !logged) {
          notifyDevToolsEnd(
            requestId, e.message, 0, {}, startTime,
            { url: fullUrl, method, actualUrl: fullUrl, headers: reqHeaders, body: bodyToMatch },
            ruleMatch, isMocked,
            { name: e.name, message: e.message }
          );
          logged = true;
        }
        throw e;
      }
    };
  }
}
