
import { loggingService } from '../utils/loggingService';
import { generateRequestId, notifyDevToolsStart, notifyDevToolsEnd } from './common';
import { RuleModificationStrategy } from './RuleModificationStrategies';
import * as DebugInterceptor from './DebugInterceptor';
import * as RequestEditor from './RequestEditor';
import { captureResponseBodyForDebugger } from './responseCapture';
import * as GlobalDelay from './GlobalDelay';

const originalXhrOpen = XMLHttpRequest.prototype.open;
const originalXhrSend = XMLHttpRequest.prototype.send;
const originalXhrSetRequestHeader = XMLHttpRequest.prototype.setRequestHeader;
const originalXhrGetAllResponseHeaders = XMLHttpRequest.prototype.getAllResponseHeaders;
const originalXhrGetResponseHeader = XMLHttpRequest.prototype.getResponseHeader;

/**
 * Capture the un-patched fetch at module load time. The XHR debugger flow
 * uses this to perform the actual upstream request — calling the patched
 * window.fetch would recurse: it would create a new MFM_REQ row in the
 * Others tab AND potentially re-trigger the same debug rule, popping up
 * a second popup for the same logical request.
 */
const originalFetchForDebug = (typeof window !== 'undefined' && window.fetch)
  ? window.fetch.bind(window)
  : null;

/**
 * Strategy to monkey-patch XMLHttpRequest.
 * Intercepts open, send, and setRequestHeader.
 */
export class XhrMonkeyPatchingStrategy {
  /**
   * @param {object} context - Shared context.
   */
  constructor(context) {
    this.context = context;
    this.active = false;
  }

  enable() {
    if (this.active) return;
    this.active = true;
    const self = this;

    // 1. Monkey-patch OPEN
    //
    // Matching is intentionally NOT performed here. On page load the
    // consumer often calls xhr.open() before inject.js has received
    // MFM_STORAGE_DATA — at that moment ruleStrategy / apiStrategy are
    // empty and any match() call returns null, leaving the URL
    // unrewritten even though send() will later be queued until
    // isReady() flips. We capture state here and defer all matching
    // (and any URL rewriting) to _executeSend(), where the queue
    // guarantees strategies are populated.
    XMLHttpRequest.prototype.open = function (method, url, ...args) {
      let fullUrl;
      try {
        // Ensure base is valid or handle cases where origin is null (e.g. sandboxed iframes)
        const base = (window.location && window.location.origin && window.location.origin !== 'null')
          ? window.location.origin
          : 'http://localhost'; // Fallback base if origin is missing/null
        fullUrl = new URL(url, base).href;
      } catch (e) {
        loggingService.error(`[mockforme] Failed to construct URL for XHR open: ${url}`, e);
        // If we can't parse URL, we can't match rules safely. Fallback to original.
        return originalXhrOpen.call(this, method, url, ...args);
      }

      this._mfm_url = fullUrl;
      this._mfm_method = method;
      this._mfm_requestId = generateRequestId();
      this._mfm_async = args[0] !== false; // Capture async flag
      this._mfm_open_args = args; // [async, user?, password?] — preserved for re-open after match
      this._mfm_logged = false; // Reset logging state
      this._mfm_timeout = false; // Reset timeout state

      // Check if this is a redirected request we should skip matching for.
      // The redirect path inside _executeSend deletes _mfm_skip_rules
      // immediately after this open() returns, so we hand off the
      // intent to a longer-lived flag (_mfm_skip_match_in_send) that
      // _executeSend honours.
      if (this._mfm_skip_rules) {
        loggingService.info(`[mockforme] Skipping matching for redirected XHR: ${fullUrl}`);
        this._mfm_skip_match_in_send = true;
        // Inherit mocked status if it was set before redirection
        if (this._mfm_is_mocked_next) {
          this._mfm_inherited_mocked = true;
          delete this._mfm_is_mocked_next;
        }
        // Note: we deliberately do NOT reset _mfm_request_headers /
        // _mfm_rule_match / _mfm_mapping here — the redirect handler
        // wants those preserved (or has already cleared them).
      } else {
        // Reset state only for non-redirected requests
        this._mfm_request_headers = null;
        this._mfm_final_headers = null;
        this._mfm_rule_match = null;
        this._mfm_mapping = null;
        this._mfm_inherited_mocked = false; // Reset for fresh requests
        this._mfm_skip_match_in_send = false;
      }

      // Always open with the original (un-rewritten) URL. If matching
      // in _executeSend determines the URL must change (mapping mock
      // URL or rule modifyQueryParams), it will call originalXhrOpen
      // again to re-open the underlying XHR with the new URL. Headers
      // are buffered in setRequestHeader (not actually applied yet),
      // so they survive the re-open and get applied by _executeSend.
      return originalXhrOpen.call(this, method, url, ...args);
    };

    // 2. Monkey-patch SETREQUESTHEADER
    // 2. Monkey-patch SETREQUESTHEADER
    XMLHttpRequest.prototype.setRequestHeader = function (header, value) {
      if (!this._mfm_request_headers) this._mfm_request_headers = {};
      this._mfm_request_headers[header] = value;
      // Buffer only
    };

    // 3. Monkey-patch SEND
    XMLHttpRequest.prototype.send = function (body) {
      if (!self.context.isEnabled()) {
        return originalXhrSend.apply(this, arguments);
      }

      // Queue if not ready
      if (!self.context.isReady()) {
        loggingService.info(`[mockforme] XHR queued (not ready) for ${this._mfm_url}`);
        const xhrInstance = this;
        const args = arguments;
        self.context.queueRequest(() => {
          // Re-check enabled when running from queue
          if (!self.context.isEnabled()) {
            originalXhrSend.apply(xhrInstance, args);
            return;
          }
          // We must manually re-trigger logic or just call send?
          self._executeSend(xhrInstance, body, args);
        });
        return;
      }

      self._executeSend(this, body, arguments);
    };

    // 4. Response Headers
    XMLHttpRequest.prototype.getAllResponseHeaders = function () {
      const original = originalXhrGetAllResponseHeaders.call(this);
      const match = this._mfm_rule_match;
      if (match && match.modificationActions?.modifyResponseHeaders?.enabled) {
        // Parse
        const headers = {};
        if (original) {
          original.trim().split(/[\r\n]+/).forEach(line => {
            const parts = line.split(': ');
            const k = parts.shift();
            const v = parts.join(': ');
            headers[k] = v;
          });
        }
        // Modify
        const modified = RuleModificationStrategy.modifyResponseHeaders(headers, match.modificationActions.modifyResponseHeaders);
        // Reconstruct
        return Object.entries(modified).map(([k, v]) => `${k}: ${v}`).join('\r\n') + '\r\n';
      }
      return original;
    };

    XMLHttpRequest.prototype.getResponseHeader = function (header) {
      // Use getAllResponseHeaders logic
      if (this._mfm_rule_match?.modificationActions?.modifyResponseHeaders?.enabled) {
        const all = this.getAllResponseHeaders();
        const lines = all.trim().split(/[\r\n]+/);
        const lower = header.toLowerCase();
        for (const line of lines) {
          const parts = line.split(': ');
          if (parts[0].toLowerCase() === lower) return parts.slice(1).join(': ');
        }
        return null;
      }
      return originalXhrGetResponseHeader.call(this, header);
    };
  }

  /**
   * Internal method to execute the XHR send logic (logging, delay, actual send).
   */
  _executeSend(xhr, body, sendArgs) {
    // ── Deferred matching ──────────────────────────────────────────
    // Matching was deferred from open() to here so that page-load
    // requests (which often call open() before MFM_STORAGE_DATA
    // arrives) get matched once strategies are populated. The send()
    // path waits on isReady() via the queue, so by the time we land
    // here the strategies are guaranteed to be loaded.
    if (!xhr._mfm_skip_match_in_send) {
      const ruleMatch = this.context.ruleStrategy.match(xhr._mfm_url, xhr._mfm_method);
      if (ruleMatch) {
        loggingService.info(`[mockforme] Rule matched for ${xhr._mfm_url}, skipping mapping.`);
        xhr._mfm_rule_match = ruleMatch;

        // Modify Query Params — may rewrite URL, requiring a re-open.
        if (ruleMatch.modificationActions?.modifyQueryParams?.enabled) {
          const newUrl = RuleModificationStrategy.modifyQueryParams(xhr._mfm_url, ruleMatch.modificationActions.modifyQueryParams);
          if (newUrl !== xhr._mfm_url) {
            xhr._mfm_url = newUrl;
            loggingService.info(`[mockforme] Modified Request URL: ${newUrl}`);
            try {
              originalXhrOpen.call(xhr, xhr._mfm_method, newUrl, ...(xhr._mfm_open_args || [xhr._mfm_async]));
            } catch (e) {
              loggingService.error('[mockforme] Failed to re-open XHR after query-param modification', e);
            }
          }
        }
      } else {
        // Check Mappings
        const mapping = this.context.apiStrategy.match(xhr._mfm_url, xhr._mfm_method);
        if (mapping) {
          xhr._mfm_mapping = mapping;
          const mockUrl = this.context.apiStrategy.getMockUrl(xhr._mfm_url);
          loggingService.info(`[mockforme] Rewriting XHR URL: ${xhr._mfm_url} -> ${mockUrl}`);
          try {
            originalXhrOpen.call(xhr, xhr._mfm_method, mockUrl, ...(xhr._mfm_open_args || [xhr._mfm_async]));
          } catch (e) {
            loggingService.error('[mockforme] Failed to re-open XHR for mapping mock URL', e);
          }
        }
      }
    }
    // Clear the skip flag so the next send() on the same XHR doesn't
    // accidentally inherit it.
    xhr._mfm_skip_match_in_send = false;
    // ── End deferred matching ──────────────────────────────────────

    const match = xhr._mfm_rule_match || this.context.ruleStrategy.match(xhr._mfm_url, xhr._mfm_method, xhr._mfm_request_headers || {}, body);

    // Apply Actions using Shared Strategy
    let finalBody = body;
    let finalHeaders = { ...(xhr._mfm_request_headers || {}) };

    if (match && match.modificationActions) {
      // Body
      finalBody = RuleModificationStrategy.modifyRequestBody(body, match.modificationActions.modifyRequestBody);
      // Headers
      finalHeaders = RuleModificationStrategy.modifyRequestHeaders(finalHeaders, match.modificationActions.modifyRequestHeaders);
    }

    // Store final state for redirection and logging
    xhr._mfm_final_body = finalBody;
    xhr._mfm_final_headers = finalHeaders;

    // Inject headers if mapping
    if (xhr._mfm_mapping) {
      const token = this.context.apiStrategy.token;
      if (token) finalHeaders['mockforme'] = token;
      else loggingService.warn("[mockforme] Token is missing for XHR!");

      if (xhr._mfm_mapping._ack) finalHeaders['x-mockforme-id'] = xhr._mfm_mapping._ack;
      // Flow-scoped mocks identify the target ApiResponse via `_ri_`
      // instead of `_ack` — see the matching block in
      // FetchMonkeyPatchingStrategy.js for the full rationale.
      if (xhr._mfm_mapping._ri_) finalHeaders['_ri_'] = xhr._mfm_mapping._ri_;
    }

    // Apply Headers
    for (const [k, v] of Object.entries(finalHeaders)) {
      originalXhrSetRequestHeader.call(xhr, k, v);
    }

    // Determine isMocked implies mapping or rule exists, or inherited from a rule-triggered redirect
    const isMocked = !!xhr._mfm_mapping || !!match || !!xhr._mfm_inherited_mocked;

    const ruleLogInfo = match ? {
      type: match.type,
      value: match.config?.value ?? match.config?.delay,
      redirectUrl: match.config?.redirectUrl ?? match.config?.url
    } : null;

    const startTime = notifyDevToolsStart(xhr._mfm_requestId, xhr._mfm_url, xhr._mfm_method, finalBody, finalHeaders, ruleLogInfo, isMocked);

    // Listeners for logging
    if (startTime) {
      this._attachListeners(xhr, startTime, match);
    }

    // ─── Outgoing-Request Editor + Live Debugger ──────────────────────
    // Both features are gated on !isMocked. We resolve the editor first
    // (pauses before the network call), then the debugger (pauses on
    // the response), so the user can chain modifier ➝ debugger.
    const editRule = (!isMocked)
      ? RequestEditor.match(xhr._mfm_method, xhr._mfm_url)
      : null;
    const debugRule = (!isMocked)
      ? DebugInterceptor.match(xhr._mfm_method, xhr._mfm_url)
      : null;

    if (editRule || debugRule) {
      this._runEditAndDebugFlow(
        xhr, finalBody, finalHeaders, editRule, debugRule, startTime, ruleLogInfo, isMocked,
      ).catch((err) => {
        loggingService.error('[mockforme] XHR editor/debugger flow failed:', err);
        if (startTime && !xhr._mfm_logged) {
          notifyDevToolsEnd(
            xhr._mfm_requestId, 'Debugger fallback: native XHR resumed', 0, {}, startTime,
            {
              url: xhr._mfm_url,
              method: xhr._mfm_method,
              actualUrl: xhr._mfm_url,
              headers: xhr._mfm_final_headers || xhr._mfm_request_headers,
              body: finalBody,
            },
            ruleLogInfo, isMocked,
            { name: err?.name || 'Error', message: err?.message || 'XHR debugger flow failed' },
          );
          xhr._mfm_logged = true;
        }
        try { originalXhrSend.call(xhr, finalBody); } catch { /* swallow */ }
      });
      return;
    }
    // ─── End Outgoing-Request Editor + Live Debugger ──────────────────

    // Handle Rule Actions
    if (match && match.strategy) {
      match.strategy.execute(match.config, { url: xhr._mfm_url, method: xhr._mfm_method })
        .then((result) => {
          if (result && result.redirectUrl) {
            // Handle Redirect
            if (startTime) {
              notifyDevToolsEnd(
                xhr._mfm_requestId, "Redirecting", 302, { 'Location': result.redirectUrl }, startTime,
                { url: xhr._mfm_url, method: xhr._mfm_method, actualUrl: xhr._mfm_url, headers: xhr._mfm_final_headers || xhr._mfm_request_headers, body: finalBody },
                ruleLogInfo, isMocked
              );
              xhr._mfm_logged = true;
            }

            loggingService.info(`[mockforme] Redirecting XHR to ${result.redirectUrl}`);

            // Store modifications to be re-applied after open()
            const redirectedHeaders = xhr._mfm_final_headers;

            // Important: flag this XHR to skip rules on the next call to avoid loops and inherit mocked status
            xhr._mfm_skip_rules = true;
            xhr._mfm_is_mocked_next = isMocked;
            xhr._mfm_rule_match = null; // Explicitly clear match to prevent re-execution

            // Re-open
            xhr.open(xhr._mfm_method, result.redirectUrl, xhr._mfm_async);

            // Re-apply the FINAL/MODIFIED headers to the new request
            if (redirectedHeaders) {
              for (const [k, v] of Object.entries(redirectedHeaders)) {
                xhr.setRequestHeader(k, v);
              }
            }

            // Clean up flag after open() has been called and handled it
            delete xhr._mfm_skip_rules;

            // Send again with final/modified body
            xhr.send(finalBody);
          } else {
            // Just send (Delay continued)
            originalXhrSend.call(xhr, finalBody);
          }
        })
        .catch(e => {
          // Timeout or error
          if (e.isMockTimeout || e.message === "Network request failed (simulated timeout)") {
            if (startTime && !xhr._mfm_logged) {
              // Explicitly notify DevTools before aborting
              notifyDevToolsEnd(
                xhr._mfm_requestId, "Timeout", 0, {}, startTime,
                { url: xhr._mfm_url, method: xhr._mfm_method, actualUrl: xhr._mfm_url, headers: xhr._mfm_final_headers || xhr._mfm_request_headers, body: finalBody },
                ruleLogInfo, isMocked,
                { name: "AbortError", message: "Timeout" }
              );
              xhr._mfm_logged = true;
              xhr._mfm_timeout = true;
            }
            // Trigger abort to notify the client
            xhr.abort();
            // Fallback: manually trigger events if abort() was quiet
            xhr.dispatchEvent(new Event('abort'));
            xhr.dispatchEvent(new Event('loadend'));
          } else {
            loggingService.error("[mockforme] Rule execution failed", e);
            originalXhrSend.call(xhr, finalBody);
          }
        });

      return; // Async handling took over
    }

    // ─── Global Others-tab Delay ────────────────────────────────────
    // Apply only on the non-mocked / non-rule path. The settings sheet
    // controls the value (in seconds). 0 = off.
    const delayValue = !isMocked ? GlobalDelay.delayMs() : 0;
    if (delayValue > 0) {
      setTimeout(() => {
        try { originalXhrSend.call(xhr, finalBody); } catch { /* swallow */ }
      }, delayValue);
      return;
    }
    // ─── End Global Others-tab Delay ────────────────────────────────

    originalXhrSend.call(xhr, finalBody);
  }

  /**
   * Combined flow that handles both the outgoing-request editor and the
   * response debugger on a single XHR. The editor (if present) pauses
   * before the network call so the user can edit headers / query params
   * / body; the debugger (if present) pauses on the response.
   *
   * Both features go through fetch (the un-patched copy captured at
   * module load) so we have full control over the request lifecycle.
   */
  async _runEditAndDebugFlow(xhr, originalBody, originalHeaders, editRule, debugRule, startTime, ruleLogInfo, isMocked) {
    let url = xhr._mfm_url;
    const method = xhr._mfm_method;
    let headers = { ...originalHeaders };
    let body = originalBody;

    // Step 1: pause for the request editor.
    if (editRule) {
      const queryParams = {};
      try {
        const u = new URL(url);
        u.searchParams.forEach((v, k) => { queryParams[k] = v; });
      } catch { /* ignore */ }

      const editResolution = await RequestEditor.intercept({
        requestId: xhr._mfm_requestId,
        ruleId: editRule.id,
        request: { method, url, headers, body },
        queryParams,
      });

      if (editResolution.cancel) {
        if (startTime && !xhr._mfm_logged) {
          notifyDevToolsEnd(
            xhr._mfm_requestId, 'Cancelled (Editor)', 0, {}, startTime,
            { url, method, actualUrl: url, headers, body },
            ruleLogInfo, isMocked,
            { name: 'AbortError', message: 'Cancelled by MockForMe request editor' },
          );
          xhr._mfm_logged = true;
        }
        this._dispatchXhrTerminal(xhr, 'abort', 0);
        return;
      }

      // Apply edits.
      try {
        const newUrl = new URL(url);
        [...newUrl.searchParams.keys()].forEach((k) => newUrl.searchParams.delete(k));
        Object.entries(editResolution.queryParams || {}).forEach(([k, v]) => {
          newUrl.searchParams.set(k, String(v ?? ''));
        });
        url = newUrl.href;
      } catch { /* leave url as-is */ }

      headers = editResolution.headers || {};
      body = editResolution.body == null ? null : editResolution.body;
    }

    // Step 2: actual upstream call (using the un-patched fetch — see
    // module top-level for why this matters).
    if (!originalFetchForDebug) {
      loggingService.warn('[mockforme] Editor/Debugger flow skipped: original fetch unavailable.');
      if (startTime && !xhr._mfm_logged) {
        notifyDevToolsEnd(
          xhr._mfm_requestId, 'Debugger fallback: original fetch unavailable', 0, {}, startTime,
          { url, method, actualUrl: url, headers, body },
          ruleLogInfo, isMocked,
          { name: 'DebuggerFallback', message: 'Original fetch unavailable' },
        );
        xhr._mfm_logged = true;
      }
      try { originalXhrSend.call(xhr, body); } catch { /* swallow */ }
      return;
    }

    const upper = method.toUpperCase();
    const allowsBody = upper !== 'GET' && upper !== 'HEAD';

    let upstreamStatus = 0;
    let upstreamHeaders = {};
    let upstreamBody = '';
    let networkError = null;
    // Apply the global delay here too — same priority as the
    // standalone XHR path above. Editor/debugger requests are
    // Others-eligible by definition (skipped for isMocked).
    if (!isMocked) {
      const dly = GlobalDelay.delayMs();
      if (dly > 0) {
        await new Promise((r) => setTimeout(r, dly));
      }
    }

    try {
      const realResponse = await originalFetchForDebug(url, {
        method,
        headers,
        body: allowsBody ? body : undefined,
        credentials: xhr.withCredentials ? 'include' : 'same-origin',
      });
      upstreamStatus = realResponse.status;
      realResponse.headers.forEach((v, k) => { upstreamHeaders[k] = v; });
      upstreamBody = await captureResponseBodyForDebugger(realResponse, xhr._mfm_requestId);
    } catch (err) {
      networkError = err;
    }

    // Step 3: if no debugger, just deliver the upstream response.
    if (!debugRule) {
      const respHeaders = upstreamHeaders;
      const respStatus = networkError ? 0 : upstreamStatus;
      const respBody = networkError ? (networkError.message || 'Network error') : upstreamBody;

      if (startTime && !xhr._mfm_logged) {
        notifyDevToolsEnd(
          xhr._mfm_requestId, respBody, respStatus, respHeaders, startTime,
          { url, method, actualUrl: url, headers, body },
          ruleLogInfo, isMocked,
          networkError ? { name: networkError.name, message: networkError.message } : null,
        );
        xhr._mfm_logged = true;
      }

      if (networkError) {
        this._dispatchXhrTerminal(xhr, 'error', 0);
        return;
      }

      this._injectXhrResponse(xhr, respStatus, respHeaders, respBody);
      this._dispatchXhrTerminal(xhr, 'load', respBody.length);
      return;
    }

    // Step 4: pause for the debugger with the captured response.
    const resolution = await DebugInterceptor.intercept({
      requestId: xhr._mfm_requestId,
      ruleId: debugRule.id,
      request: { method, url, headers, body },
      response: networkError
        ? { statusCode: 0, headers: {}, body: networkError.message || 'Network error' }
        : { statusCode: upstreamStatus, headers: upstreamHeaders, body: upstreamBody },
    });

    if (resolution.simulateTimeout) {
      if (startTime && !xhr._mfm_logged) {
        notifyDevToolsEnd(
          xhr._mfm_requestId, 'Timeout (Debugger)', 0, {}, startTime,
          { url, method, actualUrl: url, headers, body },
          ruleLogInfo, isMocked,
          { name: 'AbortError', message: 'Timeout simulated by MockForMe debugger' },
        );
        xhr._mfm_logged = true;
      }
      this._dispatchXhrTerminal(xhr, 'timeout', 0);
      return;
    }

    if (resolution.delayMs > 0) {
      await new Promise((r) => setTimeout(r, resolution.delayMs));
    }

    const finalStatus = Number(resolution.statusCode) || upstreamStatus || 200;
    const finalRespHeaders = resolution.headers && typeof resolution.headers === 'object'
      ? resolution.headers
      : upstreamHeaders;
    const finalRespBody = typeof resolution.body === 'string'
      ? resolution.body
      : (resolution.body == null ? '' : JSON.stringify(resolution.body));

    if (startTime && !xhr._mfm_logged) {
      notifyDevToolsEnd(
        xhr._mfm_requestId, finalRespBody, finalStatus, finalRespHeaders, startTime,
        { url, method, actualUrl: url, headers, body },
        ruleLogInfo, isMocked,
      );
      xhr._mfm_logged = true;
    }

    this._injectXhrResponse(xhr, finalStatus, finalRespHeaders, finalRespBody);
    this._dispatchXhrTerminal(xhr, 'load', finalRespBody.length);
  }

  /**
   * Drive an XHR through the live debugger only (kept for back-compat in
   * case callers still wire it directly; the typical path is now
   * `_runEditAndDebugFlow`).
   */
  async _runDebugFlow(xhr, finalBody, finalHeaders, debugRule, startTime, ruleLogInfo, isMocked) {
    const url = xhr._mfm_url;
    const method = xhr._mfm_method;

    // Step 1: real upstream call via the un-patched fetch we captured at
    // module load. Never go through window.fetch here — that would create
    // a duplicate Others row and recursively trigger this same debug rule.
    let upstreamStatus = 0;
    let upstreamHeaders = {};
    let upstreamBody = '';
    let networkError = null;

    if (!originalFetchForDebug) {
      loggingService.warn('[mockforme] Debugger flow skipped: original fetch unavailable.');
      if (startTime && !xhr._mfm_logged) {
        notifyDevToolsEnd(
          xhr._mfm_requestId, 'Debugger fallback: original fetch unavailable', 0, {}, startTime,
          { url, method, actualUrl: url, headers: finalHeaders, body: finalBody },
          ruleLogInfo, isMocked,
          { name: 'DebuggerFallback', message: 'Original fetch unavailable' },
        );
        xhr._mfm_logged = true;
      }
      try { originalXhrSend.call(xhr, finalBody); } catch { /* swallow */ }
      return;
    }

    try {
      const realResponse = await originalFetchForDebug(url, {
        method,
        headers: finalHeaders,
        body: method === 'GET' || method === 'HEAD' ? undefined : finalBody,
        credentials: xhr.withCredentials ? 'include' : 'same-origin',
      });
      upstreamStatus = realResponse.status;
      realResponse.headers.forEach((v, k) => { upstreamHeaders[k] = v; });
      upstreamBody = await captureResponseBodyForDebugger(realResponse, xhr._mfm_requestId);
    } catch (err) {
      networkError = err;
    }

    // Step 2: ask the widget what to do.
    const resolution = await DebugInterceptor.intercept({
      requestId: xhr._mfm_requestId,
      ruleId: debugRule.id,
      request: { method, url, headers: finalHeaders, body: finalBody },
      response: networkError
        ? { statusCode: 0, headers: {}, body: networkError.message || 'Network error' }
        : { statusCode: upstreamStatus, headers: upstreamHeaders, body: upstreamBody },
    });

    // Step 3a: simulate timeout — fail the XHR.
    if (resolution.simulateTimeout) {
      if (startTime && !xhr._mfm_logged) {
        notifyDevToolsEnd(
          xhr._mfm_requestId, 'Timeout (Debugger)', 0, {}, startTime,
          { url, method, actualUrl: url, headers: finalHeaders, body: finalBody },
          ruleLogInfo, isMocked,
          { name: 'AbortError', message: 'Timeout simulated by MockForMe debugger' },
        );
        xhr._mfm_logged = true;
      }
      this._dispatchXhrTerminal(xhr, 'timeout', 0);
      return;
    }

    // Step 3b: optional artificial delay.
    if (resolution.delayMs > 0) {
      await new Promise((r) => setTimeout(r, resolution.delayMs));
    }

    // Step 3c: assemble the final response payload.
    const finalStatus = Number(resolution.statusCode) || upstreamStatus || 200;
    const finalRespHeaders = resolution.headers && typeof resolution.headers === 'object'
      ? resolution.headers
      : upstreamHeaders;
    const finalRespBody = typeof resolution.body === 'string'
      ? resolution.body
      : (resolution.body == null ? '' : JSON.stringify(resolution.body));

    if (startTime && !xhr._mfm_logged) {
      notifyDevToolsEnd(
        xhr._mfm_requestId, finalRespBody, finalStatus, finalRespHeaders, startTime,
        { url, method, actualUrl: url, headers: finalHeaders, body: finalBody },
        ruleLogInfo, isMocked,
      );
      xhr._mfm_logged = true;
    }

    // Step 4: drive the XHR. Override its readonly properties with the
    // user-edited values, then dispatch lifecycle events so the page's
    // existing handlers run as if the network had returned this.
    this._injectXhrResponse(xhr, finalStatus, finalRespHeaders, finalRespBody);
    this._dispatchXhrTerminal(xhr, 'load', finalRespBody.length);
  }

  /** Override xhr.status / responseText / response / header getters. */
  _injectXhrResponse(xhr, status, headers, body) {
    const define = (key, value) => {
      try {
        Object.defineProperty(xhr, key, { configurable: true, get: () => value });
      } catch { /* some envs forbid; ignore */ }
    };
    define('status', status);
    define('statusText', status === 200 ? 'OK' : '');
    define('readyState', 4);
    define('responseText', body);
    define('response', body);
    define('responseURL', xhr._mfm_url || '');

    const headerString = Object.entries(headers || {})
      .map(([k, v]) => `${k}: ${v}`)
      .join('\r\n') + '\r\n';

    xhr.getAllResponseHeaders = () => headerString;
    xhr.getResponseHeader = (name) => {
      if (!name) return null;
      const lower = String(name).toLowerCase();
      const found = Object.keys(headers || {}).find((k) => k.toLowerCase() === lower);
      return found ? headers[found] : null;
    };
  }

  /** Dispatch the chosen terminal event plus loadend, mirroring native XHR. */
  _dispatchXhrTerminal(xhr, eventName, byteSize = 0) {
    const make = (type) => {
      try {
        return new ProgressEvent(type, { lengthComputable: true, loaded: byteSize, total: byteSize });
      } catch {
        return new Event(type);
      }
    };

    try {
      const stateEvt = new Event('readystatechange');
      if (typeof xhr.onreadystatechange === 'function') {
        try { xhr.onreadystatechange.call(xhr, stateEvt); } catch { /* swallow */ }
      }
      xhr.dispatchEvent(stateEvt);
    } catch { /* swallow */ }

    const evt = make(eventName);
    if (typeof xhr[`on${eventName}`] === 'function') {
      try { xhr[`on${eventName}`].call(xhr, evt); } catch { /* swallow */ }
    }
    xhr.dispatchEvent(evt);

    const endEvt = make('loadend');
    if (typeof xhr.onloadend === 'function') {
      try { xhr.onloadend.call(xhr, endEvt); } catch { /* swallow */ }
    }
    xhr.dispatchEvent(endEvt);
  }

  _attachListeners(xhr, startTime, match) {
    const logEnd = (body, status, error = null, isUpdate = false) => {
      if (xhr._mfm_logged && !isUpdate) return;
      if (!isUpdate) xhr._mfm_logged = true;

      const headerStr = xhr.getAllResponseHeaders();
      const headers = {};
      if (headerStr) {
        headerStr.trim().split(/[\r\n]+/).forEach(line => {
          const parts = line.split(': ');
          const key = parts.shift();
          const val = parts.join(': ');
          headers[key] = val;
        });
      }
      const isMocked = !!xhr._mfm_mapping || !!match || !!xhr._mfm_inherited_mocked;
      const ruleMatch = match; // Use passed match

      const ruleLogInfo = ruleMatch ? {
        type: ruleMatch.type,
        value: ruleMatch.config?.value ?? ruleMatch.config?.delay,
        redirectUrl: ruleMatch.config?.redirectUrl ?? ruleMatch.config?.url
      } : null;

      const bodyToLog = xhr._mfm_timeout ? "Timeout" : body;
      const statusToLog = xhr._mfm_timeout ? 0 : status;
      const errorToLog = xhr._mfm_timeout ? { name: "AbortError", message: "Timeout" } : error;

      notifyDevToolsEnd(
        xhr._mfm_requestId, bodyToLog, statusToLog, headers, startTime,
        { url: xhr._mfm_url, method: xhr._mfm_method, actualUrl: xhr._mfm_url, headers: xhr._mfm_final_headers || xhr._mfm_request_headers, body: xhr._mfm_final_body },
        ruleLogInfo, isMocked, errorToLog
      );
    };

    // Add streaming detection
    xhr.addEventListener('readystatechange', function () {
      if (this.readyState === 2) { // HEADERS_RECEIVED
        this._mfm_chunks_reported = 0;
        // Always report start of response to clear "Loading" state in UI
        logEnd("[Loading Response...]", this.status, null, true);
      }

      if (this.readyState === 3) { // LOADING
        try {
          const currentText = this.responseText;
          this._mfm_chunks_reported = (this._mfm_chunks_reported || 0) + 1;

          // Only report updates occasionally to avoid spamming
          if (this._mfm_chunks_reported <= 10 || this._mfm_chunks_reported % 10 === 0) {
            logEnd(currentText + "\n... [Streaming Active]", this.status, null, true);
          }
        } catch {
          // responseText might not be available yet or binary
        }
      }
    });

    xhr.addEventListener('load', function () {
      let body = '';
      try {
        if (!this.responseType || this.responseType === 'text') {
          body = this.responseText;
        } else if (this.responseType === 'json') {
          body = JSON.stringify(this.response);
        } else {
          // Try to see if it's convertible, or just describe it
          body = `[${this.responseType}]`;
        }
      } catch (e) {
        body = `[Error reading response: ${e.message}]`;
      }
      logEnd(body, this.status);
    });
    xhr.addEventListener('abort', function () {
      logEnd("Aborted", 0, { name: "AbortError", message: "Aborted" });
    });
    xhr.addEventListener('error', function () {
      logEnd("Error", 0, { name: "Error", message: "Network Error" });
    });
  }
}
