
import { loggingService } from '../utils/loggingService';

/**
 * Generates a random UUID-like string for request identification.
 * @returns {string} - A random UUID string.
 */
export const generateRequestId = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

/**
 * Sanitizes the request/response body for safe postMessage transmission.
 * Handles FormData, URLSearchParams, Blob, ArrayBuffer, etc.
 * @param {any} body - The body to sanitize.
 * @returns {string|object} - The sanitized body.
 */
export const sanitizeBody = (body) => {
  if (body === null || body === undefined) return body;
  if (typeof body === 'string') return body;

  // Handle FormData
  if (typeof FormData !== 'undefined' && body instanceof FormData) {
    const obj = {};
    body.forEach((value, key) => {
      if (value instanceof File || value instanceof Blob) {
        obj[key] = `[${value.constructor.name}: ${value.name || 'blob'}]`;
      } else {
        obj[key] = value;
      }
    });
    return obj;
  }

  // Handle URLSearchParams
  if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) {
    const obj = {};
    body.forEach((value, key) => {
      obj[key] = value;
    });
    return obj;
  }

  // Handle Blob/File
  if (typeof Blob !== 'undefined' && body instanceof Blob) {
    return `[${body.constructor.name}: ${body.name || 'blob'}]`;
  }

  // Handle ArrayBuffer/DataView
  if (typeof ArrayBuffer !== 'undefined' && (body instanceof ArrayBuffer || ArrayBuffer.isView(body))) {
    return `[${body.constructor.name}: ${body.byteLength} bytes]`;
  }

  return body;
};

/**
 * Notifies the DevTools (via Content Script) that a request has started.
 * @param {string} requestId - Unique ID for the request.
 * @param {string} url - The request URL.
 * @param {string} method - The HTTP method.
 * @param {any} body - The request body.
 * @param {object} headers - The request headers.
 * @param {object|null} ruleMatch - The matched rule, if any.
 * @param {boolean} isMocked - Whether the request matches a mock mapping.
 * @returns {number} - The timestamp when the request started.
 */
export const notifyDevToolsStart = (requestId, url, method, body = null, headers = {}, ruleMatch = null, isMocked = false) => {
  const timestamp = Date.now();
  const payload = {
    url,
    actualUrl: url,
    method,
    headers: headers || {},
    body: sanitizeBody(body),
    timestamp,
    isMocked: !!isMocked
  };

  if (ruleMatch) {
    let action = 'Unknown';
    let value = '';

    const v = ruleMatch.value ?? 0;
    const r = ruleMatch.redirectUrl || '';

    if (ruleMatch.type === 'delay') {
      action = 'Delay';
      value = `${v}s`;
    } else if (ruleMatch.type === 'timeout') {
      action = 'Timeout';
      value = `${v}s`;
    } else if (ruleMatch.type === 'delay_and_timeout') {
      action = 'Delay and Timeout';
      value = `${v}s`;
    } else if (ruleMatch.type === 'delay_and_redirect') {
      action = 'Delay and Redirect';
      value = `${v}s -> ${r}`;
    }

    payload.rule = {
      action,
      config: { value }
    };
    loggingService.info(`[mockforme] Notify Start: Rule included:`, payload.rule);
  }

  loggingService.info(`[mockforme] notifyDevToolsStart: id=${requestId}, isMocked=${isMocked}, type=${isMocked ? "MOCKED" : "OTHER"}`);

  window.postMessage({
    type: "MFM_LOG_REQUEST",
    requestId,
    payload
  }, "*");

  // Support mfm-widget protocol
  window.postMessage({
    type: "MFM_REQ",
    payload: {
      requestId,
      interceptionType: isMocked ? "MOCKED" : "OTHER",
      request: {
        method: payload.method,
        url: payload.url,
        headers: payload.headers,
        body: payload.body
      },
      timestamp: payload.timestamp
    }
  }, "*");

  return timestamp;
};

/**
 * Notifies the DevTools (via Content Script) that a request has completed (or failed).
 * @param {string} requestId - Unique ID for the request.
 * @param {any} responseBody - The response body.
 * @param {number} status - The HTTP status code.
 * @param {object} headers - The response headers.
 * @param {number} startTime - The timestamp when the request started.
 * @param {object} requestDetails - Original request details {url, method, ...}.
 * @param {object|null} ruleMatch - The matched rule, if any.
 * @param {boolean} isMocked - Whether the request was mocked.
 * @param {object|null} error - Error object if failed.
 */
export const notifyDevToolsEnd = (requestId, responseBody, status, headers, startTime, requestDetails = {}, ruleMatch = null, isMocked = false, error = null) => {
  const endTime = Date.now();
  const duration = startTime ? (endTime - startTime) : 0;

  loggingService.info(`[mockforme_log_issue] Notify End: ${requestId} Status: ${status} Duration: ${duration}ms Error:`, error);

  window.postMessage({
    type: "MFM_LOG_RESPONSE",
    requestId,
    payload: {
      body: responseBody,
      status,
      headers,
      timestamp: endTime,
      duration,
      request: {
        ...requestDetails,
        body: sanitizeBody(requestDetails.body)
      },
      error: error ? true : false,
      name: error?.name,
      message: error?.message,
      isMocked: !!isMocked,
      rule: ruleMatch
    }
  }, "*");

  loggingService.info(`[mockforme] notifyDevToolsEnd: id=${requestId}, isMocked=${isMocked}, type=${isMocked ? "MOCKED" : "OTHER"}`);

  // Support mfm-widget protocol
  window.postMessage({
    type: "MFM_RES",
    payload: {
      requestId,
      interceptionType: isMocked ? "MOCKED" : "OTHER",
      request: {
        ...requestDetails,
        body: sanitizeBody(requestDetails.body)
      },
      response: {
        statusCode: status,
        headers: headers,
        body: responseBody,
        endTime: new Date(endTime).toISOString()
      },
      rule: ruleMatch,
      timestamp: startTime || endTime
    }
  }, "*");
};
