import { loggingService } from '../utils/loggingService';

const DEFAULT_TIMEOUT_MS = 1500;
const DEFAULT_MAX_CHARS = 1024 * 1024;

/**
 * Safely captures response text for the live debugger without waiting forever.
 *
 * Some responses are streams, long-polling requests, or very large payloads.
 * Calling `response.clone().text()` directly can block the debugger popup until
 * the body ends. This helper races the body read against a short timeout and
 * returns a clear placeholder when the body cannot be captured in time.
 *
 * @example
 * const body = await captureResponseBodyForDebugger(response, requestId);
 */
export async function captureResponseBodyForDebugger(response, requestId, options = {}) {
  if (!response) return '';

  const timeoutMs = options.timeoutMs || DEFAULT_TIMEOUT_MS;
  const maxChars = options.maxChars || DEFAULT_MAX_CHARS;

  try {
    const text = await readTextWithTimeout(response, timeoutMs);
    return text;
  } catch (error) {
    loggingService.warn(
      `[mockforme] Debugger response capture skipped for ${requestId}: ${error.message}`,
    );
    return '[Response body unavailable: stream is still loading or too large]';
  }
}

/** Race `response.clone().text()` against a timeout so debugger UI can open. */
async function readTextWithTimeout(response, timeoutMs) {
  const bodyRead = response.clone().text();
  const timeout = new Promise((_, reject) => {
    setTimeout(() => reject(new Error(`body read timed out after ${timeoutMs}ms`)), timeoutMs);
  });

  return Promise.race([bodyRead, timeout]);
}

/** Keep debugger payloads bounded to avoid expensive postMessage copies. */
function truncateText(text, maxChars) {
  if (typeof text !== 'string') return '';
  if (text.length <= maxChars) return text;
  return `${text.slice(0, maxChars)}\n\n[Response truncated by MockForMe debugger]`;
}
