import { loggingService } from '../utils/loggingService';

/** Direct console.log gated on the widget's "Debug logs" toggle.
 *  Reads localStorage on every call (cheap, single key). */
function mfmLog(...args) {
  try {
    if (typeof localStorage === 'undefined') return;
    const raw = localStorage.getItem('MFM_DEBUG_LOGS');
    const flag = raw ? JSON.parse(raw) : null;
    if (!flag?.enabled) return;
    // eslint-disable-next-line no-console
    console.log('[MFM]', ...args);
  } catch { /* swallow */ }
}

/**
 * RequestEditor — runtime state + helpers for the outgoing-request editor.
 *
 * Mirrors `DebugInterceptor` but for the OUTGOING side: matches a request
 * before it goes out, posts MFM_REQUEST_EDIT_REQ with the original
 * (method, url, headers, body, queryParams), waits for the user's edits
 * via MFM_REQUEST_EDIT_RES, and resolves with the modified payload.
 *
 * The widget owns the rule list. We get it via three channels:
 *   1. localStorage["MFM_REQUEST_EDITOR_RULES"] — written on every toggle.
 *   2. window.postMessage("MFM_REQUEST_EDIT_RULES_UPDATE", { rules }).
 *   3. The "storage" event for cross-tab updates.
 *
 * Matching is exact `(method, url)` to mirror the widget UX where the
 * user opted-in for one specific request from the Others tab.
 */

const STORAGE_KEY = 'MFM_REQUEST_EDITOR_RULES';

let rules = [];
const pendingResolvers = new Map();

/** Default wait time before we give up on the user (ms). */
const DEFAULT_AWAIT_MS = 5 * 60 * 1000;
/** Short guard: if the popup never becomes visible, do not strand the request. */
const DEFAULT_POPUP_ACK_MS = 10000;
const REQUEST_POST_RETRY_MS = 250;

/** Pull rules from localStorage; returns [] on parse failure / missing storage. */
function loadFromStorage() {
  try {
    if (typeof localStorage === 'undefined') return [];
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((r) => r && r.enabled);
  } catch {
    return [];
  }
}

/** Replace the active rule list (called when widget pushes update). */
export function setRequestEditorRules(next) {
  if (!Array.isArray(next)) {
    rules = [];
  } else {
    rules = next.filter((rule) => rule && rule.enabled);
  }
  mfmLog('inject.js editor rules updated', { count: rules.length });
}

/** Read-only snapshot, mostly for diagnostics. */
export function getRequestEditorRules() {
  return rules.slice();
}

/**
 * Find an active rule that matches (method, url) exactly.
 *
 * In-memory only — the in-memory cache is kept in sync via three
 * channels (in priority order):
 *   1. Synchronous DOM `mfm:rule-sync` event from the same window —
 *      runs on the same call stack as the widget toggle, so the cache
 *      is updated BEFORE the next request fires (no race).
 *   2. `MFM_REQUEST_EDIT_RULES_UPDATE` postMessage from cross-window
 *      consumers / as a backup.
 *   3. `storage` event from cross-tab updates.
 *
 * Per-match localStorage reads are not used — they were too slow on
 * busy apps and the synchronous DOM event makes them unnecessary.
 *
 * If for any reason the cache is empty when match runs (consumer mounted
 * before any rules synced), we fall back to a single localStorage read
 * to handle that edge.
 */
export function match(method, url) {
  if (!method || !url) return null;

  // Edge: if cache is empty, do a one-shot localStorage read as a
  // safety net (e.g. consumer mounted but no rule-sync event has fired
  // yet). Single read, not per-call.
  if (!rules.length) {
    rules = loadFromStorage();
    if (!rules.length) return null;
  }

  const upper = String(method).toUpperCase();
  return (
    rules.find((rule) => {
      if (!rule.enabled || String(rule.method).toUpperCase() !== upper) return false;

      if (rule.matchType === 'PATH') {
        try {
          const rulePath = new URL(rule.url, 'http://localhost').pathname;
          const targetPath = new URL(url, 'http://localhost').pathname;
          return rulePath === targetPath;
        } catch {
          return rule.url === url;
        }
      }

      return rule.url === url;
    }) || null
  );
}

/**
 * Pause the OUTGOING request and ask the widget what to do.
 *
 * @returns {Promise<object>} resolves with the user's edits, or the
 *                            original request if the widget never replies.
 */
export function intercept({ requestId, ruleId, request, queryParams, timeoutMs = DEFAULT_AWAIT_MS }) {
  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      if (pendingResolvers.has(requestId)) {
        pendingResolvers.delete(requestId);
        loggingService.warn(
          `[mockforme] RequestEditor: timed out waiting for widget reply on ${requestId}`,
        );
        resolve(forwardOriginal(requestId, request, queryParams));
      }
    }, timeoutMs);

    const postEditRequest = () => {
      window.postMessage(
        {
          type: 'MFM_REQUEST_EDIT_REQ',
          payload: { requestId, ruleId, request, queryParams, timestamp: Date.now() },
        },
        '*',
      );
    };

    const ackTimer = setTimeout(() => {
      const entry = pendingResolvers.get(requestId);
      if (!entry || entry.acknowledged) return;

      clearTimeout(entry.timer);
      clearInterval(entry.retryTimer);
      pendingResolvers.delete(requestId);
      loggingService.warn(
        `[mockforme] RequestEditor: popup was not acknowledged for ${requestId}; forwarding original`,
      );
      resolve(forwardOriginal(requestId, request, queryParams));
    }, DEFAULT_POPUP_ACK_MS);

    pendingResolvers.set(requestId, {
      resolve,
      timer,
      ackTimer,
      retryTimer: null,
      acknowledged: false,
    });

    loggingService.info('[mockforme] RequestEditor: posting edit request', {
      requestId,
      ruleId,
      method: request?.method,
      url: request?.url,
    });

    mfmLog('inject.js editor pause', {
      requestId, ruleId, method: request?.method, url: request?.url,
    });

    try {
      postEditRequest();
      const entry = pendingResolvers.get(requestId);
      if (entry) {
        entry.retryTimer = setInterval(() => {
          const pending = pendingResolvers.get(requestId);
          if (!pending || pending.acknowledged) return;
          postEditRequest();
        }, REQUEST_POST_RETRY_MS);
      }
    } catch (err) {
      loggingService.error('[mockforme] RequestEditor: failed to post intercept req', err);
      clearTimeout(timer);
      clearTimeout(ackTimer);
      pendingResolvers.delete(requestId);
      resolve(forwardOriginal(requestId, request, queryParams));
    }
  });
}

/** Build a "no-op" resolution that forwards the original request. */
function forwardOriginal(requestId, request, queryParams) {
  const headers = {};
  Object.entries(request?.headers || {}).forEach(([k, v]) => {
    headers[k] = String(v == null ? '' : v);
  });
  return {
    requestId,
    cancel: false,
    headers,
    queryParams: queryParams || {},
    body: typeof request?.body === 'string' ? request.body : null,
  };
}

/** Called from inject.js when MFM_REQUEST_EDIT_RES arrives. */
export function resolvePending(payload) {
  if (!payload || !payload.requestId) {
    loggingService.warn('[mockforme] RequestEditor: ignored resolution without requestId', payload);
    return;
  }

  const entry = pendingResolvers.get(payload.requestId);
  if (!entry) {
    loggingService.warn('[mockforme] RequestEditor: no pending request for resolution', payload);
    return;
  }

  loggingService.info('[mockforme] RequestEditor: resolving edit request', {
    requestId: payload.requestId,
    cancel: !!payload.cancel,
  });

  clearTimeout(entry.timer);
  clearTimeout(entry.ackTimer);
  clearInterval(entry.retryTimer);
  pendingResolvers.delete(payload.requestId);
  entry.resolve(payload);
}

/** Called from inject.js when the widget confirms the edit popup is visible. */
export function acknowledgePending(payload) {
  if (!payload || !payload.requestId) {
    loggingService.warn('[mockforme] RequestEditor: ignored ack without requestId', payload);
    return;
  }

  const entry = pendingResolvers.get(payload.requestId);
  if (!entry) {
    loggingService.warn('[mockforme] RequestEditor: no pending request for ack', payload);
    return;
  }

  entry.acknowledged = true;
  clearTimeout(entry.ackTimer);
  clearInterval(entry.retryTimer);
  loggingService.info('[mockforme] RequestEditor: popup acknowledged', {
    requestId: payload.requestId,
  });
}

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

// Seed in-memory rules from localStorage on module load.
rules = loadFromStorage();

// 1. Synchronous DOM event from the widget — same-window primary
//    channel. The widget dispatches this BEFORE returning from the
//    user's click handler, so by the time the user's app fires its
//    next fetch, our in-memory cache is already current.
if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
  document.addEventListener('mfm:rule-sync', (event) => {
    const detail = event && event.detail;
    if (!detail || detail.kind !== 'editor') return;
    setRequestEditorRules(detail.payload?.rules || []);
  });
}

// 2. Storage event from cross-tab updates.
if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
  window.addEventListener('storage', (event) => {
    if (event.key !== STORAGE_KEY) return;
    rules = loadFromStorage();
  });
}
