import { loggingService } from '../utils/loggingService';

/** Direct console.log gated on the widget's "Debug logs" toggle. */
function mfmLog(...args) {
  try {
    if (typeof localStorage === 'undefined') return;
    const raw = localStorage.getItem('MFM_DEBUG_LOGS');
    const flag = raw ? JSON.parse(raw) : null;
    if (!flag?.enabled) return;
    // eslint-disable-next-line no-console
    console.log('[MFM]', ...args);
  } catch { /* swallow */ }
}

/**
 * DebugInterceptor — runtime state + helpers for the live network debugger.
 *
 * The widget owns the rule list. It notifies us via three channels:
 *   1. localStorage["MFM_INTERCEPTOR_RULES"] — written on every toggle
 *      (this is how the widget itself survives a page reload).
 *   2. window.postMessage("MFM_DEBUG_RULES_UPDATE", { rules })
 *      — fast in-memory update for the same tab.
 *   3. The "storage" event — fired in OTHER tabs on the same origin
 *      when localStorage changes.
 *
 * We listen on (2) and (3), and additionally re-read (1) inside match()
 * as a defensive fallback. That eliminates a class of races where the
 * widget UI updates the badge but inject.js hadn't yet received the
 * postMessage when the next request fired.
 *
 * On a match we post MFM_DEBUG_INTERCEPT_REQ and return a Promise that
 * resolves when the widget posts MFM_DEBUG_INTERCEPT_RES with edits.
 */

const STORAGE_KEY = 'MFM_INTERCEPTOR_RULES';

let debugRules = [];
const pendingResolvers = new Map();

/** Default wait time before we give up on the user (ms). */
const DEFAULT_AWAIT_MS = 5 * 60 * 1000;

/** Pull rules from localStorage; returns [] on parse failure / missing storage. */
function loadFromStorage() {
  try {
    if (typeof localStorage === 'undefined') return [];
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((r) => r && r.enabled);
  } catch {
    return [];
  }
}

/** Replace the active rule list (called when widget pushes update). */
export function setDebugRules(rules) {
  if (!Array.isArray(rules)) {
    debugRules = [];
  } else {
    debugRules = rules.filter((rule) => rule && rule.enabled);
  }
  mfmLog('inject.js debugger rules updated', { count: debugRules.length });
}

/** Read-only snapshot, mostly for diagnostics. */
export function getDebugRules() {
  return debugRules.slice();
}

/**
 * Find an active rule that matches (method, url) exactly.
 *
 * In-memory only. The cache is kept in sync via the synchronous DOM
 * `mfm:rule-sync` event (same window), `MFM_DEBUG_RULES_UPDATE`
 * postMessage (cross-window) and `storage` events (cross-tab). See
 * RequestEditor.js for the full reasoning.
 */
export function match(method, url) {
  if (!method || !url) return null;

  // Edge: empty cache fallback to localStorage one-shot.
  if (!debugRules.length) {
    debugRules = loadFromStorage();
    if (!debugRules.length) return null;
  }

  const upper = String(method).toUpperCase();
  return (
    debugRules.find((rule) => {
      if (!rule.enabled || String(rule.method).toUpperCase() !== upper) return false;

      if (rule.matchType === 'PATH') {
        try {
          const rulePath = new URL(rule.url, 'http://localhost').pathname;
          const targetPath = new URL(url, 'http://localhost').pathname;
          return rulePath === targetPath;
        } catch {
          return rule.url === url;
        }
      }

      return rule.url === url;
    }) || null
  );
}

/**
 * Pause the request and ask the widget what to do.
 *
 * @param {object} params
 * @param {string} params.requestId
 * @param {string} params.ruleId
 * @param {object} params.request   { method, url, headers, body }
 * @param {object} params.response  { statusCode, headers, body }
 * @param {number} [params.timeoutMs]
 * @returns {Promise<object>} resolves with the user's edits, or the original
 *                            response if the widget never replies.
 */
export function intercept({ requestId, ruleId, request, response, timeoutMs = DEFAULT_AWAIT_MS }) {
  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      if (pendingResolvers.has(requestId)) {
        pendingResolvers.delete(requestId);
        loggingService.warn(
          `[mockforme] DebugInterceptor: timed out waiting for widget reply on ${requestId}`,
        );
        resolve({
          requestId,
          simulateTimeout: false,
          delayMs: 0,
          statusCode: response?.statusCode ?? 200,
          headers: response?.headers || {},
          body: response?.body,
        });
      }
    }, timeoutMs);

    pendingResolvers.set(requestId, { resolve, timer });

    loggingService.info('[mockforme] DebugInterceptor: posting intercept request', {
      requestId,
      ruleId,
      method: request?.method,
      url: request?.url,
      statusCode: response?.statusCode,
    });

    mfmLog('inject.js debugger pause', {
      requestId, ruleId, method: request?.method, url: request?.url, status: response?.statusCode,
    });

    try {
      window.postMessage(
        {
          type: 'MFM_DEBUG_INTERCEPT_REQ',
          payload: { requestId, ruleId, request, response, timestamp: Date.now() },
        },
        '*',
      );
    } catch (err) {
      loggingService.error('[mockforme] DebugInterceptor: failed to post intercept req', err);
      clearTimeout(timer);
      pendingResolvers.delete(requestId);
      resolve({
        requestId,
        simulateTimeout: false,
        delayMs: 0,
        statusCode: response?.statusCode ?? 200,
        headers: response?.headers || {},
        body: response?.body,
      });
    }
  });
}

/** Called from inject.js when MFM_DEBUG_INTERCEPT_RES arrives. */
export function resolvePending(payload) {
  if (!payload || !payload.requestId) {
    loggingService.warn('[mockforme] DebugInterceptor: ignored resolution without requestId', payload);
    return;
  }

  const entry = pendingResolvers.get(payload.requestId);
  if (!entry) {
    loggingService.warn('[mockforme] DebugInterceptor: no pending request for resolution', payload);
    return;
  }

  loggingService.info('[mockforme] DebugInterceptor: resolving intercept request', {
    requestId: payload.requestId,
    statusCode: payload.statusCode,
    simulateTimeout: !!payload.simulateTimeout,
  });

  clearTimeout(entry.timer);
  pendingResolvers.delete(payload.requestId);
  entry.resolve(payload);
}

/** Convenience: produce request id used elsewhere if caller doesn't have one. */
export function generateDebugId() {
  return `dbg_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

debugRules = loadFromStorage();

// Synchronous DOM event from the widget (same-window primary channel).
if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
  document.addEventListener('mfm:rule-sync', (event) => {
    const detail = event && event.detail;
    if (!detail || detail.kind !== 'debugger') return;
    setDebugRules(detail.payload?.rules || []);
  });
}

if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
  window.addEventListener('storage', (event) => {
    if (event.key !== STORAGE_KEY) return;
    debugRules = loadFromStorage();
  });
}
