
import { loggingService } from '../utils/loggingService';
import { checkFlowMockMatch } from './flowMocks';

/**
 * Strategy for handling rules (delay, timeout, redirection).
 */
import { DelayStrategy, DelayAndTimeoutStrategy, DelayAndRedirectStrategy } from './RuleActionStrategies';

const VITE_API_BASE_URL = import.meta.env.VITE_API_BASE_URL;

/**
 * Strategy for handling rules (delay, timeout, redirection).
 */
export class RuleStrategy {
  constructor() {
    this.rules = [];
    this.strategies = {
      'delay': new DelayStrategy(),
      'delay_and_timeout': new DelayAndTimeoutStrategy(),
      'delay_and_redirect': new DelayAndRedirectStrategy(),
      'timeout': new DelayAndTimeoutStrategy() // Map timeout to DelayAndTimeout (0 delay)
    };
  }

  /**
   * Updates the rules list.
   * @param {Array} rules - The new list of rules.
   */
  update(rules) {
    this.rules = rules || [];
  }

  /**
   * Checks if a request matches any active rule.
   * @param {string} url - The request URL.
   * @param {string} method - The request method.
   * @param {object} headers - The request headers.
   * @param {any} body - The request body.
   * @returns {object|null} - The matched rule strategy and config.
   */
  match(url, method, headers = {}, body = null) {
    if (!this.rules || !Array.isArray(this.rules)) return null;

    for (const r of this.rules) {
      const rule = r.rule || r;
      if (!rule) continue;

      // Helper to check URL match
      const checkMatch = (reqUrl, reqVal, reqOp) => {
        const isFullUrl = reqVal.startsWith('http://') || reqVal.startsWith('https://');
        let target = reqUrl;
        if (!isFullUrl) {
          try { target = new URL(reqUrl).pathname; } catch (e) { }
        }
        if (reqOp === "contains") return target.includes(reqVal || "");
        if (reqOp === "equals") return target === (reqVal || "");
        return false;
      };

      // Helper to check simple string match
      const checkMatchSimple = (actual, target, op) => {
        if (actual === null || actual === undefined) return false;
        const sActual = String(actual);
        const sTarget = String(target || "");
        if (op === "contains") return sActual.includes(sTarget);
        if (op === "equals") return sActual === sTarget;
        return false;
      };

      // Gather conditions to match
      let conditions = [];
      if (rule.conditions && Array.isArray(rule.conditions) && rule.conditions.length > 0) {
        conditions = rule.conditions;
      } else if (rule.URL && rule.URL.condition) {
        // Fallback for legacy format
        conditions = [{
          type: 'URL',
          operator: rule.URL.condition.operator,
          value: rule.URL.condition.value
        }];
      }

      if (conditions.length === 0) continue;

      let matched = true;
      for (const cond of conditions) {
        let condMatched = false;
        if (cond.type === 'URL') {
          condMatched = checkMatch(url, cond.value, cond.operator);
        } else if (cond.type === 'Method') {
          const methodVal = cond.value || '';
          if (cond.operator === 'equals' && method.toUpperCase() === methodVal.toUpperCase()) condMatched = true;
          else if (cond.operator === 'contains' && method.toUpperCase().includes(methodVal.toUpperCase())) condMatched = true;
        } else if (cond.type === 'QUERY_PARAM') {
          try {
            const urlObj = new URL(url);
            const paramVal = urlObj.searchParams.get(cond.key);
            condMatched = checkMatchSimple(paramVal, cond.value, cond.operator);
          } catch (e) { }
        } else if (cond.type === 'REQUEST_HEADER') {
          const headKey = Object.keys(headers).find(k => k.toLowerCase() === (cond.key || '').toLowerCase());
          const headVal = headKey ? headers[headKey] : undefined;
          condMatched = checkMatchSimple(headVal, cond.value, cond.operator);
        } else if (cond.type === 'REQUEST_BODY') {
          let bodyToMatch = body;
          if (typeof body === 'string') {
            try { bodyToMatch = JSON.parse(body); } catch (e) { }
          }
          if (typeof bodyToMatch === 'object' && bodyToMatch !== null) {
            const bodyVal = bodyToMatch[cond.key];
            condMatched = checkMatchSimple(bodyVal, cond.value, cond.operator);
          } else if (typeof bodyToMatch === 'string') {
            if (!cond.key) {
              condMatched = checkMatchSimple(bodyToMatch, cond.value, cond.operator);
            }
          }
        }

        if (!condMatched) {
          matched = false;
          break;
        }
      }

      if (matched) {
        // New Structure: Use timingAction strictly
        const timingAction = rule.timingAction || {};
        const actions = timingAction.actions || {};
        const activeAction = timingAction.activeAction;
        const modificationActions = rule.modificationActions;
        const hasTiming = activeAction && this.strategies[activeAction];

        // Match if we have a timing action OR modification actions
        if (hasTiming || modificationActions) {
          loggingService.info(`[mockforme] Rule matched for ${url}. Action: ${activeAction}, Mods: ${!!modificationActions}`);

          let config = {};
          let strategy = null;

          if (hasTiming) {
            strategy = this.strategies[activeAction];
            if (activeAction === 'delay') config = actions.delay;
            else if (activeAction === 'delay_and_timeout') config = actions.delay_and_timeout;
            else if (activeAction === 'delay_and_redirect') config = actions.delay_and_redirect;
            else if (activeAction === 'timeout') config = { value: 0 };
          }

          return {
            strategy: strategy,
            config: config,
            type: activeAction, // Legacy type
            modificationActions: modificationActions // New property
          };
        }
      }
    }
    return null;
  }
}

/**
 * Strategy for handling API interception and mocking.
 */
export class ApiStrategy {
  constructor() {
    this.mappings = [];
    this.token = "";
  }

  /**
   * Updates mappings and token.
   * @param {Array} mappings - List of API mappings.
   * @param {string} token - The auth token.
   */
  update(mappings, token) {
    this.mappings = mappings || [];
    this.token = token || "";
  }

  /**
   * Checks if a request matches any mock mapping.
   * @param {string} url - The request URL.
   * @param {string} method - The request method.
   * @returns {object|null} - The matching mapping object or null.
   */
  match(url, method) {
    // Flow-scoped mocks take precedence over the user-managed mapping
    // library. They live in their own in-memory map (see flowMocks.js)
    // and only exist for the duration of an active flow run.
    const flowMatch = checkFlowMockMatch(url, method);
    if (flowMatch) {
      loggingService.info(`[mockforme] Flow Mock Match: ${method} ${url} -> ${flowMatch.apiEndpoint}`);
      return flowMatch;
    }

    if (!this.mappings || !Array.isArray(this.mappings)) return null;

    let urlObj;
    try {
      urlObj = new URL(url);
    } catch (e) {
      loggingService.error("[mockforme] Invalid URL:", url);
      return null;
    }
    const pathname = urlObj.pathname;

    for (const m of this.mappings) {
      // Check Method first
      if (m.apiMethod && m.apiMethod.toLowerCase() !== method.toLowerCase()) {
        continue;
      }

      let patternStr = m.apiEndpoint;
      // Determine if mapping is full URL or path
      const isFullUrl = patternStr.startsWith('http://') || patternStr.startsWith('https://');
      const target = isFullUrl ? url : pathname;

      if (patternStr.includes(':any')) {
        try {
          // Escape special regex characters
          const escaped = patternStr.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
          // Replace :any with [^/]+ (one or more non-slash chars) and anchor
          const regexStr = '^' + escaped.replace(/:any/g, '[^/]+') + '$';
          const pattern = new RegExp(regexStr);

          if (pattern.test(target)) return m;
        } catch (e) {
          loggingService.error("[mockforme] Error creating regex for mapping:", patternStr, e);
        }
      } else {
        // Strict equality check
        if (target === patternStr) return m;
      }
    }
    return null;
  }

  /**
   * Constructs the mock URL for a given request URL.
   * @param {string} url - The original URL.
   * @returns {string} - The mocked URL (pointing to mockforme service).
   */
  getMockUrl(url) {
    try {
      const urlObj = new URL(url);
      // We want the relative path: pathname + search

      let pathname = urlObj.pathname;
      // Encode double slashes to avoid backend normalization (// -> /%2F)
      // NOTE: This only affects the path. Query strings (urlObj.search) are preserved as-is.
      if (pathname.includes('//')) {
        pathname = pathname.replace(/\/\//g, '/%2F');
      }

      let relativeUrl = pathname + urlObj.search;

      // Remove leading slash (or encoded slash start) to avoid double slash when appending to .../mockforme/
      if (relativeUrl.startsWith('/')) {
        relativeUrl = relativeUrl.substring(1);
      }

      const finalUrl = `${VITE_API_BASE_URL}/mockforme/${relativeUrl}`;
      return finalUrl;
    } catch (e) {
      loggingService.error("[mockforme] Invalid URL for mock construction:", url, e);
      return url;
    }
  }
}
