
import { loggingService } from '../utils/loggingService';

/**
 * Base abstract strategy for rule execution.
 */
class RuleActionStrategy {
  execute(ruleConfig, requestContext) {
    throw new Error("Method 'execute' must be implemented.");
  }
}

/**
 * Strategy for Delay action.
 */
export class DelayStrategy extends RuleActionStrategy {
  async execute(ruleConfig, requestContext) {
    const delayInSeconds = ruleConfig.value || 0;
    loggingService.info(`[mockforme] Delaying request to ${requestContext.url} by ${delayInSeconds}s`);
    await new Promise(resolve => setTimeout(resolve, delayInSeconds * 1000));
    // After delay, we don't return anything special, the caller proceeds.
  }
}

/**
 * Strategy for Delay and Timeout.
 */
export class DelayAndTimeoutStrategy extends RuleActionStrategy {
  async execute(ruleConfig, requestContext) {
    const delayInSeconds = ruleConfig.value ?? ruleConfig.delay ?? 0;
    loggingService.info(`[mockforme] Delay and Timeout request to ${requestContext.url}. Waiting ${delayInSeconds}s then timing out.`);

    await new Promise(resolve => setTimeout(resolve, delayInSeconds * 1000));

    // Throw an error to simulate timeout
    const error = new TypeError("Network request failed (simulated timeout)");
    error.isMockTimeout = true;
    throw error;
  }
}

/**
 * Strategy for Delay and Redirect.
 */
export class DelayAndRedirectStrategy extends RuleActionStrategy {
  async execute(ruleConfig, requestContext) {
    const delayInSeconds = ruleConfig.value ?? ruleConfig.delay ?? 0;
    const redirectUrl = ruleConfig.redirectUrl || ruleConfig.url;

    loggingService.info(`[mockforme] Delay and Redirect request to ${requestContext.url}. Waiting ${delayInSeconds}s then redirecting to ${redirectUrl}`);

    await new Promise(resolve => setTimeout(resolve, delayInSeconds * 1000));

    if (!redirectUrl) {
      loggingService.warn("[mockforme] Redirect URL is missing in rule config.");
      return; // Or throw?
    }

    // Return the redirect URL so the caller can hijack the request
    return { redirectUrl };
  }
}
