/**
 * flowMocks (chrome-extension)
 * ─────────────────────────────
 * Per-flow-run mock registry — mirror of the in-page mockforme-npm
 * version (`mockforme-npm/src/client/flowMocks.js`). Same shape, same
 * lifecycle, same isolation guarantees.
 *
 * Lives entirely in-memory inside the injected script. When the flow
 * runner posts `MFM_FLOW_MOCK_SET`, the inject.js message listener
 * routes it here. Reads are consulted by `ApiStrategy.match()` BEFORE
 * the user-managed mappings, so flow mocks take precedence for the
 * duration of the run but never touch the saved mock library.
 *
 * The wire shape of each api entry matches `ApiStrategy.mappings`:
 *   { apiMethod, apiEndpoint, _ack, _ri_ }
 * so downstream interceptor code consumes it without conditional logic.
 */

/** Map<runId, Array<{ apiMethod, apiEndpoint, _ack, _ri_ }>>. */
const flowMocksByRun = new Map();

/**
 * Replace the mock list for a given flow run. Sending a new list with
 * the same runId atomically swaps the previous list.
 */
export function setFlowMocks(runId, apis) {
    if (!runId) return;
    flowMocksByRun.set(String(runId), Array.isArray(apis) ? apis : []);
}

/** Drop the mock list for a flow run. Safe to call with an unknown runId. */
export function clearFlowMocks(runId) {
    if (!runId) return;
    flowMocksByRun.delete(String(runId));
}

/** True when at least one flow run currently has mocks registered. */
export function hasAnyFlowMocks() {
    return flowMocksByRun.size > 0;
}

/**
 * Look up a flow-scoped mock for a full URL + method. Returns a mapping
 * object — same shape as one entry in `ApiStrategy.mappings` — so the
 * fetch / xhr interceptors can use it unchanged. Returns null on miss.
 *
 * Matching rules:
 *   - case-insensitive method match
 *   - exact pathname OR `:any` placeholder match against either the full
 *     URL or the pathname (whichever the endpoint pattern looks like)
 */
export function checkFlowMockMatch(fullUrl, method) {
    if (flowMocksByRun.size === 0) return null;

    let pathname;
    try {
        pathname = new URL(fullUrl).pathname;
    } catch {
        return null;
    }

    for (const apis of flowMocksByRun.values()) {
        for (const m of apis) {
            if (m.apiMethod
                && m.apiMethod.toLowerCase() !== method.toLowerCase()) {
                continue;
            }
            const patternStr = m.apiEndpoint;
            const isFullUrl = patternStr.startsWith('http://')
                || patternStr.startsWith('https://');
            const target = isFullUrl ? fullUrl : pathname;
            if (patternStr.includes(':any')) {
                try {
                    const escaped = patternStr.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                    const regexStr = '^' + escaped.replace(/:any/g, '[^/]+') + '$';
                    if (new RegExp(regexStr).test(target)) return m;
                } catch {
                    // ignore malformed pattern
                }
            } else if (target === patternStr) {
                return m;
            }
        }
    }
    return null;
}
