import { loggingService } from './src/utils/loggingService';
import { RuleStrategy, ApiStrategy } from './src/strategies/MockStrategies';
import { FetchMonkeyPatchingStrategy } from './src/strategies/FetchMonkeyPatchingStrategy';
import { XhrMonkeyPatchingStrategy } from './src/strategies/XhrMonkeyPatchingStrategy';
import * as DebugInterceptor from './src/strategies/DebugInterceptor';
import * as RequestEditor from './src/strategies/RequestEditor';
import * as GlobalDelay from './src/strategies/GlobalDelay';
import { setFlowMocks, clearFlowMocks } from './src/strategies/flowMocks';

(function () {
    if (window.__MFM_INJECTED) {
        return;
    }
    window.__MFM_INJECTED = true;

    // --- State ---
    let g_ready = false;
    let g_enabled = true;
    let g_organisationId = "";
    const requestQueue = [];

    // --- Strategies ---
    const ruleStrategy = new RuleStrategy();
    const apiStrategy = new ApiStrategy();

    const context = {
        ruleStrategy,
        apiStrategy,
        isEnabled: () => g_enabled,
        isReady: () => g_ready,
        queueRequest: (callback) => requestQueue.push(callback)
    };

    const fetchStrategy = new FetchMonkeyPatchingStrategy(context);
    const xhrStrategy = new XhrMonkeyPatchingStrategy(context);

    // --- Enable Patching ---
    fetchStrategy.enable();
    xhrStrategy.enable();

    // --- Configuration Update Helper ---
    const updateConfiguration = (payload) => {
        loggingService.info("[mockforme] Updating configuration/strategies.", payload);
        const { _rules, mappings, enabled, token, _o } = payload;

        ruleStrategy.update(_rules);
        apiStrategy.update(mappings, token);
        g_organisationId = _o ?? "";

        // Sync token to localStorage for widget
        if (token) {
            const currentTokenInLocalStorage = localStorage.getItem('MFM_TOKEN');
            if (!currentTokenInLocalStorage) {
                localStorage.setItem('MFM_TOKEN', token);
            }
        } else if (token === null || token === undefined || token === "") {
            localStorage.removeItem('MFM_TOKEN');
        }

        if (enabled !== undefined) {
            g_enabled = enabled;
            sessionStorage.setItem('MFM_IS_INTERCEPT_ENABLED', enabled ? 'true' : 'false');
        }
        g_ready = true;

        // Release queue
        loggingService.info(`[mockforme] Releasing ${requestQueue.length} queued requests.`);
        requestQueue.forEach(cb => {
            try { cb(); } catch (e) {
                loggingService.error("[mockforme] Error in queued request callback:", e);
            }
        });
        requestQueue.length = 0;

        // Send updated mappings to widget if it's already requested them
        if (window === window.top) {
            window.postMessage({
                type: "MFM_RES_MAPPINGS",
                payload: transformToWidgetFormat(mappings, _rules, token, g_organisationId)
            }, "*");
        }
    };

    const transformToWidgetFormat = (mappings, rules, token = null, organisationId = "") => {
        const apis = (mappings || []).map(m => ({
            method: m.apiMethod || "GET",
            url: m.apiEndpoint || ""
        }));

        const transformedRules = (rules || []).map(r => {
            const rule = r.rule || r;
            // Map internal timing action type to widget-friendly type or default to MODIFY if modificationActions exist
            let type = "MODIFY";
            if (rule.timingAction?.activeAction === "delay_and_redirect") type = "REDIRECT";
            else if (rule.timingAction?.activeAction === "delay_and_timeout") type = "TIMEOUT";
            else if (rule.timingAction?.activeAction === "delay") type = "DELAY";

            return {
                ruleName: r.ruleName || "Unnamed Rule",
                type: type,
                conditions: rule.conditions || [],
                timingAction: rule.timingAction || {},
                modificationActions: rule.modificationActions || {}
            };
        });

        return { apis, rules: transformedRules, token, _o: organisationId ?? "" };
    };

    // --- Message Listener ---
    window.addEventListener("message", (event) => {
        if (event.source !== window) return;

        const { type, payload } = event.data;
        if (type && type.startsWith("MFM_")) {
            loggingService.info(`[mockforme] [inject] Received message: ${type}`, payload);
        }

        // Internal MFM Storage Sync
        if (type === "MFM_STORAGE_DATA") {
            updateConfiguration(payload);
        }

        // Widget Communication Protocol (Outgoing from Widget)
        if (type === "MFM_REQ_SAVED_MAPPINGS") {
            loggingService.info("[mockforme] [inject] MFM_REQ_SAVED_MAPPINGS received. Sending local data.");
            const currentData = transformToWidgetFormat(apiStrategy.mappings, ruleStrategy.rules, apiStrategy.token, g_organisationId);
            window.postMessage({
                type: "MFM_RES_MAPPINGS",
                payload: currentData
            }, "*");
        }

        if (type === "MFM_REQ_MAPPINGS") {
            loggingService.info("[mockforme] [inject] MFM_REQ_MAPPINGS received. Sending current data and requesting refresh.");

            // 1. Send current (cached) data immediately so widget isn't blank
            // const currentData = transformToWidgetFormat(apiStrategy.mappings, ruleStrategy.rules, apiStrategy.token);
            // window.postMessage({
            //     type: "MFM_RES_MAPPINGS",
            //     payload: currentData
            // }, "*");

            // 2. Trigger fresh reload from background
            window.postMessage({ type: "MFM_INTERNAL_RELOAD_MAPPINGS" }, "*");
        }

        if (type === "MFM_SUBMIT_TOKEN") {
            // Forward to content script/background to save in storage
            window.postMessage({
                type: "MFM_INTERNAL_SAVE_TOKEN",
                payload: { token: payload.token }
            }, "*");
        }

        if (type === "MFM_DEL_CLIENT_TOKEN") {
            window.postMessage({
                type: "MFM_INTERNAL_DELETE_TOKEN"
            }, "*");
        }

        if (type === "MFM_TOGGLE_INTERCEPTION") {
            window.postMessage({
                type: "MFM_INTERNAL_TOGGLE_ENABLED",
                payload: { enabled: payload.enabled }
            }, "*");
        }

        if (type === "MFM_LOG_INFO" || type === "MFM_LOG_WARN" || type === "MFM_LOG_ERROR") {
            const loggerMethod = type === "MFM_LOG_INFO" ? "info" : (type === "MFM_LOG_WARN" ? "warn" : "error");
            loggingService[loggerMethod](...payload);
        }

        // Live debugger — widget pushes the active rule list.
        if (type === "MFM_DEBUG_RULES_UPDATE") {
            DebugInterceptor.setDebugRules(payload?.rules || []);
        }

        // Live debugger — widget responds to a paused request with edits.
        if (type === "MFM_DEBUG_INTERCEPT_RES") {
            DebugInterceptor.resolvePending(payload);
        }

        // Outgoing-request editor — widget pushes the active rule list.
        if (type === "MFM_REQUEST_EDIT_RULES_UPDATE") {
            RequestEditor.setRequestEditorRules(payload?.rules || []);
        }

        // Outgoing-request editor — widget responds to a paused outgoing request with edits.
        if (type === "MFM_REQUEST_EDIT_ACK") {
            RequestEditor.acknowledgePending(payload);
        }

        // Outgoing-request editor — widget responds to a paused outgoing request with edits.
        if (type === "MFM_REQUEST_EDIT_RES") {
            RequestEditor.resolvePending(payload);
        }

        // Global Others-tab delay — widget pushes the active value.
        if (type === "MFM_GLOBAL_DELAY_UPDATE") {
            GlobalDelay.set(payload);
        }

        // ── Flow-scoped mocks (widget -> injected) ──────────────────
        // Mirror of the mockforme-npm WidgetManager cases. Live in a
        // separate in-memory registry (flowMocks.js) so the user's
        // saved mappings are never touched.
        //
        // On SET we ALSO flip `g_enabled` to true synchronously — a
        // typical flow run sends MFM_FLOW_MOCK_SET immediately followed
        // by MFM_TOGGLE_INTERCEPTION, and the toggle takes a round-trip
        // through the content script to update g_enabled. Without the
        // synchronous flip here, fetches between SET and the toggle's
        // round-trip-complete would bypass the interceptor entirely.
        if (type === "MFM_FLOW_MOCK_SET") {
            setFlowMocks(payload?.runId, payload?.apis || []);
            if (!g_enabled) {
                g_enabled = true;
                try {
                    sessionStorage.setItem('MFM_IS_INTERCEPT_ENABLED', 'true');
                } catch { /* ignore quota / disabled storage */ }
            }
        }
        if (type === "MFM_FLOW_MOCK_CLEAR") {
            clearFlowMocks(payload?.runId);
            // Don't force-disable here — the widget's flowMockBridge
            // sends the restored interception state via a separate
            // MFM_TOGGLE_INTERCEPTION immediately after CLEAR.
        }
    });

    // --- Timeout Safety ---
    // If not ready after 2 seconds, release queue to avoid breaking the site
    setTimeout(() => {
        if (!g_ready) {
            loggingService.warn("[mockforme] Timed out waiting for configuration. Releasing queue (disabled).");
            g_enabled = false;
            g_ready = true;
            requestQueue.forEach(cb => cb());
            requestQueue.length = 0;
        }
    }, 2000);

    // --- Initialize from Dataset (Synchronous) ---
    const currentScript = document.currentScript;
    if (currentScript && currentScript.dataset.mfmSettings) {
        try {
            const settings = JSON.parse(currentScript.dataset.mfmSettings);
            updateConfiguration(settings);
        } catch (e) {
            loggingService.error("[mockforme] Failed to parse initial data from dataset", e);
        }
    } else if (window.__MFM_INITIAL_DATA) {
        try {
            updateConfiguration(window.__MFM_INITIAL_DATA);
            delete window.__MFM_INITIAL_DATA;
        } catch (e) {
            loggingService.error("[mockforme] Failed to parse initial data from window", e);
        }
    }
    // --- Global Error Handlers ---
    // Listen for uncaught exceptions in the consumer application and report them
    window.addEventListener('error', (event) => {
        if (!g_enabled) return;
        const { message, filename, lineno, colno, error } = event;

        window.postMessage({
            type: "MFM_PAGE_ERROR",
            payload: {
                message,
                stack: error?.stack,
                file: filename,
                line: lineno,
                col: colno,
                timestamp: Date.now()
            }
        }, "*");
    });

    window.addEventListener('unhandledrejection', (event) => {
        if (!g_enabled) return;
        const { reason } = event;

        window.postMessage({
            type: "MFM_PAGE_ERROR",
            payload: {
                message: `Unhandled Rejection: ${reason?.message || reason}`,
                stack: reason?.stack,
                timestamp: Date.now()
            }
        }, "*");
    });
})();
