import { loggingService } from '../utils/loggingService';

/**
 * GlobalDelay — uniform delay applied to every Others-tab-eligible
 * outgoing request, controlled from the widget's Settings sheet.
 *
 * Wire-up:
 *   1. Widget posts MFM_GLOBAL_DELAY_UPDATE → set() updates state.
 *   2. Persisted in localStorage["MFM_GLOBAL_DELAY"] for resilience
 *      across hard refreshes (mirrors the rule-sync race fix).
 *   3. Fetch / XHR strategies call delayMs() and await it before the
 *      upstream call, ONLY on the non-mocked / non-rule path.
 */

const STORAGE_KEY = 'MFM_GLOBAL_DELAY';

let state = { enabled: false, seconds: 0 };
let lastStorageReadAt = 0;

const STORAGE_REFRESH_INTERVAL_MS = 500;

function loadFromStorage() {
  try {
    if (typeof localStorage === 'undefined') return { enabled: false, seconds: 0 };
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { enabled: false, seconds: 0 };
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return { enabled: false, seconds: 0 };
    return {
      enabled: !!parsed.enabled && Number.isFinite(parsed.seconds) && parsed.seconds > 0,
      seconds: Number.isFinite(parsed.seconds) ? Number(parsed.seconds) : 0,
    };
  } catch {
    return { enabled: false, seconds: 0 };
  }
}

/** Replace the active delay (called when widget pushes update). */
export function set(next) {
  if (!next || typeof next !== 'object') {
    state = { enabled: false, seconds: 0 };
    lastStorageReadAt = Date.now();
    return;
  }
  state = {
    enabled: !!next.enabled && Number.isFinite(next.seconds) && next.seconds > 0,
    seconds: Number.isFinite(next.seconds) ? Number(next.seconds) : 0,
  };
  lastStorageReadAt = Date.now();
  loggingService.info(
    `[mockforme] GlobalDelay: ${state.enabled ? `${state.seconds}s` : 'off'}`,
  );
}

/** Read-only snapshot, mostly for diagnostics. */
export function snapshot() {
  return { ...state };
}

/**
 * Returns the delay (in milliseconds) that should be applied before the
 * NEXT Others-eligible request. Returns 0 when no delay is active.
 *
 * Refreshes from localStorage on a throttled cadence so settings tweaks
 * take effect even if the postMessage was missed (race fix mirrors the
 * one in DebugInterceptor / RequestEditor).
 */
export function delayMs() {
  const now = Date.now();
  if (now - lastStorageReadAt > STORAGE_REFRESH_INTERVAL_MS) {
    state = loadFromStorage();
    lastStorageReadAt = now;
  }
  return state.enabled && state.seconds > 0 ? Math.round(state.seconds * 1000) : 0;
}

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

state = loadFromStorage();
lastStorageReadAt = Date.now();

if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
  window.addEventListener('storage', (event) => {
    if (event.key !== STORAGE_KEY) return;
    state = loadFromStorage();
    lastStorageReadAt = Date.now();
  });
}
