
import { loggingService } from '../utils/loggingService';

/**
 * Strategy for Modification Actions (Headers, Body, Query Params).
 * This logic is shared between XHR and Fetch strategies.
 */
export class RuleModificationStrategy {

  /**
   * Modifies Query Parameters of the given URL.
   * @param {string} url - The original URL.
   * @param {object} actions - The modifyQueryParams actions { add: [], remove: [] }.
   * @returns {string} - The modified URL.
   */
  static modifyQueryParams(url, actions) {
    if (!actions || !actions.enabled) return url;
    try {
      const urlObj = new URL(url);
      if (actions.remove && Array.isArray(actions.remove)) {
        actions.remove.forEach(key => urlObj.searchParams.delete(key));
      }
      if (actions.add && Array.isArray(actions.add)) {
        actions.add.forEach(item => urlObj.searchParams.set(item.key, item.value));
      }
      return urlObj.href;
    } catch (e) {
      loggingService.error("[mockforme] Error modifying query params:", e);
      return url;
    }
  }

  /**
   * Modifies Request Body (assumes JSON).
   * @param {string|object} body - The original body.
   * @param {object} actions - The modifyRequestBody actions { add: [], remove: [], update: [] }.
   * @returns {string|object} - The modified body (stringified JSON usually).
   */
  static modifyRequestBody(body, actions) {
    if (!actions || !actions.enabled) return body;
    try {
      let jsonBody = {};
      let isString = false;

      if (typeof body === 'string') {
        try {
          jsonBody = JSON.parse(body);
          isString = true;
        } catch (e) {
          // If not JSON, we cannot modify it safely with these rules
          return body;
        }
      } else if (typeof body === 'object' && body !== null) {
        jsonBody = body;
      } else {
        return body;
      }

      // Apply modifications
      if (actions.remove && Array.isArray(actions.remove)) {
        actions.remove.forEach(k => delete jsonBody[k]);
      }
      if (actions.add && Array.isArray(actions.add)) {
        actions.add.forEach(item => jsonBody[item.key] = item.value);
      }
      if (actions.update && Array.isArray(actions.update)) {
        actions.update.forEach(item => jsonBody[item.key] = item.value);
      }

      return isString ? JSON.stringify(jsonBody) : jsonBody;
    } catch (e) {
      loggingService.error("[mockforme] Error modifying request body:", e);
      return body;
    }
  }

  /**
   * Modifies Request Headers.
   * @param {object} headersMap - A simple map of headers { key: value }.
   * @param {object} actions - The modifyRequestHeaders actions { add: [], remove: [] }.
   * @returns {object} - The modified headers map.
   */
  static modifyRequestHeaders(headersMap, actions) {
    if (!actions || !actions.enabled) return headersMap;
    // Clone to avoid mutating original if needed (though caller usually passes a copy/fresh object)
    const newHeaders = { ...headersMap };

    if (actions.remove && Array.isArray(actions.remove)) {
      actions.remove.forEach(k => delete newHeaders[k]);
    }
    if (actions.add && Array.isArray(actions.add)) {
      actions.add.forEach(item => newHeaders[item.key] = item.value);
    }
    return newHeaders;
  }

  /**
   * Modifies Response Headers.
   * @param {object} headersMap - A simple map of headers { key: value }.
   * @param {object} actions - The modifyResponseHeaders actions { add: [], remove: [] }.
   * @returns {object} - The modified headers map.
   */
  static modifyResponseHeaders(headersMap, actions) {
    if (!actions || !actions.enabled) return headersMap;
    const newHeaders = {};

    // Normalize keys to lowercase for consistent handling if desired, 
    // but browsers preserve case usually. 
    // Actions might specify case.

    // Copy original
    for (const k in headersMap) {
      newHeaders[k] = headersMap[k];
    }

    // Remove (case-insensitive check recommended for headers)
    if (actions.remove && Array.isArray(actions.remove)) {
      actions.remove.forEach(remKey => {
        // Find key in newHeaders that matches remKey case-insensitively
        const match = Object.keys(newHeaders).find(k => k.toLowerCase() === remKey.toLowerCase());
        if (match) delete newHeaders[match];
      });
    }

    // Add/Update
    if (actions.add && Array.isArray(actions.add)) {
      actions.add.forEach(item => {
        newHeaders[item.key] = item.value;
      });
    }

    return newHeaders;
  }
}
